/**
 * The side-effectful half of a VM teardown, behind a seam so the decision ladder
 * in `destroyVmIdempotent` can be exercised without a hypervisor.
 * `test/vm-lifecycle.test.ts` drives it with an in-memory fake.
 */
export type VmDestroyHost = {
  /** Ground truth from the hypervisor. "unknown" when it could not be read — never a guess. */
  probe: (vmid: number) => Promise<"present" | "absent" | "unknown">;
  /** Best-effort stop; may reject if the VM is already stopped or gone. */
  stop: (vmid: number) => Promise<void>;
  /** The destructive call. */
  destroy: (vmid: number) => Promise<void>;
};

export type DestroyOutcome = {
  /** True when THIS call issued the destroy and the VM is verified gone afterwards. */
  destroyed: boolean;
  /** True when the VM was already absent, so no destructive call was issued. */
  alreadyAbsent: boolean;
  detail: string;
};

/**
 * Destroy a VM in a way that is SAFE TO RUN TWICE, and that never claims a
 * teardown it did not observe.
 *
 * INCIDENT (found in audit, 2026-07-27 — worker/index.ts `reinstall`): REINSTALL
 * is destroy-then-provision, and the worker retries a failed job up to
 * MAX_ATTEMPTS times. `destroyVm` issued `DELETE /qemu/<vmid>` unconditionally
 * and did not tolerate the VM already being gone. So when attempt 1 destroyed the
 * VM and then failed anywhere in the re-provision that follows (a snippet write,
 * a clone timeout, a config POST), attempts 2 and 3 both died on the very first
 * step — `Configuration file '…/<vmid>.conf' does not exist` — and never reached
 * the provision that was supposed to rebuild the machine. The job ended FAILED,
 * REINSTALL is in VM_STATE_FAILURE_JOBS so the server was flipped to ERROR, and
 * the customer was left with no VM at all: the retry mechanism itself converted a
 * recoverable mid-reinstall failure into permanent destruction. `remove()` in the
 * same file already tolerated the absent case, which is what made the omission
 * here an oversight rather than a policy.
 *
 * The ladder:
 *   1. PROBE FIRST. An absent VM means there is nothing to destroy — return
 *      without issuing any destructive call at all.
 *   2. "unknown" does NOT block the destroy (the caller has already decided this
 *      vmid is to be torn down, and the vmid is not in question), but it is
 *      carried into the detail so nothing downstream reads it as a clean run.
 *   3. TOLERATE a vmid-anchored absent error from the destroy itself — that is
 *      the retry racing a previous attempt that actually succeeded.
 *   4. VERIFY AFTER. Re-probe; if the VM is still present the destroy did not
 *      happen and we throw, rather than let a caller delete the database rows
 *      that are the only remaining handle on a live machine.
 */
export async function destroyVmIdempotent(
  host: VmDestroyHost,
  vmid: number
): Promise<DestroyOutcome> {
  const beforeState = await host.probe(vmid);
  if (beforeState === "absent") {
    return {
      destroyed: false,
      alreadyAbsent: true,
      detail: `VM ${vmid} was already absent — no destroy was issued`,
    };
  }

  // Stop first. A stop failure is not fatal: the VM may already be stopped, and a
  // real blocker (a config lock, a running backup) will surface on the destroy.
  try {
    await host.stop(vmid);
  } catch {
    /* already stopped, or gone — the destroy below is the authority */
  }

  try {
    await host.destroy(vmid);
  } catch (e) {
    if (!isVmAbsentError(e, vmid)) throw e;
    return {
      destroyed: false,
      alreadyAbsent: true,
      detail: `VM ${vmid} disappeared before the destroy landed — treating as already torn down`,
    };
  }

  // Never report a teardown we did not observe.
  const afterState = await host.probe(vmid);
  if (afterState === "present") {
    throw new Error(
      `destroy of VM ${vmid} reported success but the VM is still present on the hypervisor — ` +
        `refusing to continue, because the caller would delete the only records that still point at it.`
    );
  }
  return {
    destroyed: true,
    alreadyAbsent: false,
    detail:
      afterState === "absent"
        ? `VM ${vmid} destroyed and verified gone`
        : `VM ${vmid} destroy completed, but its post-destroy state could not be read back`,
  };
}

