/**
 * A failed job's charge was just refunded to the wallet: reverse any partner
 * commission earned on that charge's invoice with it (owner's rule, 2026-09-29 —
 * a refund comes off the commission; voided if unpaid, netted off the next payout
 * if already paid). The invoice id is carried on the job payload by the charge
 * site (lib/disk-expand.ts, lib/dedicated-ip-purchase.ts, lib/resize.ts); a job
 * queued before that existed has none and is skipped. Keyed per job, so a
 * re-run can never reverse twice. Never throws.
 */
async function reverseCommissionForFailedJob(job: Job, invoiceId: unknown, cents: number, what: string) {
  if (typeof invoiceId !== "string" || !invoiceId || cents <= 0) return;
  await reverseCommissionSafely(`failed ${job.type} job=${job.id}`, () =>
    reversePartnerCommissionForRefund({ invoiceId, refundCents: cents, key: `job:${job.id}`, reason: `refund: failed ${what}` }),
  );
}

/**
 * Refund a per-server disk expansion that was paid for but never delivered.
 *
 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
 * really grown, so that field is the ground truth for "did the customer get what
 * they paid for". We refund only when it never reached the job's target — which
 * also keeps this safe against the partial-success case (disk grown, filesystem
 * left for the customer to grow by hand): that path completes successfully, sets
 * extraDiskGB, and is therefore never refunded.
 *
 * Idempotent per job via the reconcile audit marker.
 */
async function reconcileFailedDiskExpand(job: Job) {
  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number; invoiceId?: string };
  const cents = p.prorateCents ?? 0;
  if (cents <= 0 || !job.serverId) return;

  const already = await db.auditLog.findFirst({
    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
  });
  if (already) return;

      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
    });
    // Only an UPGRADE charge was a commissionable sale that is now refunded; a
    // down-reversal claws back a credit, which never earned commission.
    if (p.direction === "up") await reverseCommissionForFailedJob(job, p.invoiceId, cents, "upgrade");
  } catch (e: any) {
    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
    await db.auditLog.create({
      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
    }).catch(() => {});
  }
}

export async function runJob(job: Job, table: Record<string, (job: Job) => Promise<void>> = handlers) {
  // The job is already atomically claimed (status RUNNING, attempts incremented)
  // by the loop's compare-and-swap before we get here — see the CAS in main().
  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
  try {
    const handler = table[job.type];
    if (!handler) throw new Error(`No handler for job type ${job.type}`);
    await handler(job);
    // Clear any error left over from an earlier failed attempt of THIS job. Without
    // this, a job that failed once (error persisted, status QUEUED for retry) and
    // then succeeded on a later attempt ends up DONE with a stale, misleading error
    // still attached — indistinguishable from an actual silent failure to anyone
    // reading Job.error (confirmed: a real PROVISION did exactly this today).
    await db.job.update({ where: { id: job.id }, data: { status: "DONE", error: null, finishedAt: new Date() } });
    console.log(`[worker] job ${job.id} DONE`);
  } catch (e: any) {
    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
    // leak the server's root password into the thrown message. Redact it before
    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
    // sever the match. Best-effort — never let redaction lookup fail the job path.
    if (job.serverId) {
      try {
        const s = await db.server.findUnique({
          where: { id: job.serverId },
          select: { rootPassword: true, rootPasswordEnc: true },
        });
        const pw = s ? serverRootPassword(s) : null;
        if (pw) error = error.split(pw).join("***");
      } catch {
        /* best-effort redaction */
      }
    }
    error = error.slice(0, 2000);
    console.error(`[worker] job ${job.id} FAILED: ${error}`);
    const current = await db.job.findUnique({ where: { id: job.id } });
    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
    await db.job.update({
      where: { id: job.id },
      data: { status: retriable ? "QUEUED" : "FAILED", error, ...(retriable ? {} : { finishedAt: new Date() }) },
    });
    if (!retriable) {
      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
      // Persist terminal job failures to ErrorLog (deduped by fingerprint) so the
      // admin Error Logs view surfaces what broke on the customer side, not just
      // the transient Job.error. logError is already non-throwing; guard anyway.
      await logError(`job.${String(job.type).toLowerCase()}`, new Error(error), {
        source: "job",
        jobId: job.id,
        serverId: job.serverId ?? undefined,
      }).catch(() => {});
      if (job.serverId) {
        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
        if (stillExists) {
          // Only jobs that actually change the VM's run/disk state should strand the
          // server in ERROR. Side operations — backup, snapshot-create, the control-
          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
          // never touch the VM's run state; their failures surface via the executor's
          // own notification and must NOT flip the whole server to ERROR (a failed
          // backup was wrongly making the server look like it had shut down).
          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
            await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
          }
          // A terminally-failed PROVISION must not leak its allocated dedicated IP,
          // nor free a NAT IP its surviving VM still holds — see cleanupFailedProvision.
          if (job.type === "PROVISION") {
            await cleanupFailedProvision(job.serverId);
            // Tell the customer: persist the reason on the row + in-app + email.
            await notifyProvisionFailed(stillExists, error).catch((err) =>
              console.error(`[worker] notify provision failure ${job.id} failed`, err)
            );
            // Deploy-funnel: an ASYNC provisioning failure the customer never saw as
            // an inline wizard error — record it so the admin funnel can attribute a
            // bottom-of-funnel drop to a BUG rather than abandonment.
            await recordDeployFunnelError({
              product: stillExists.gamePlanId ? "game" : "vps",
              step: "Provision",
              stepIndex: 9,
              errorCode: "PROVISION_FAILED",
              errorMessage: (error.split("\n")[0] || error).slice(0, 300),
              userId: stillExists.userId,
            });
          }
        }
      }
    }
  }
}

/**
 * Clean up after a terminally-failed PROVISION. Releases a dedicated IP back to
 * the pool (deleting the billable OVH Virtual MAC) and clears the UNIQUE
 * Server.ipAddress ONLY for a dedicated server, whose address really did return
 * to the pool. A NAT server's private IP is still bound to its surviving VM's
 * ipconfig0 on the bridge, so nulling Server.ipAddress would let pickFreeIp hand
 * the same IP to another VM → a duplicate-IP collision (audit 2026-08-01). Both
 * the runJob catch-path and reapStuckJobs call this, so neither can leak an IP.
 */
async function cleanupFailedProvision(serverId: string): Promise<void> {
  if (SANDBOX) return;
  // Capture whether it was a dedicated IP BEFORE release nulls the row's serverId.
  const dedicated = await db.dedicatedIp.findUnique({ where: { serverId }, select: { id: true } });
  await releaseDedicatedIp(serverId).catch((err) =>
    console.error(`[worker] release dedicated IP on failed provision for ${serverId}`, err)
  );
  if (dedicated) {
    await db.server.update({ where: { id: serverId }, data: { ipAddress: null } }).catch(() => {});
  }

  }
}

/**
 * How many times a job may be interrupted by a worker restart before it is
 * given up on. A restart is the PLATFORM's doing, not the job's — it must not
 * burn one of the job's own MAX_ATTEMPTS (2026-10-01: a customer's Valheim
 * PROVISION was killed twice in one morning by two deploys and marked FAILED
 * "Worker restarted mid-job" on the second, with a healthy half-built VM
 * behind it). The counter lives in `payload._restarts` so a handler that
 * crash-loops the worker still terminates.
 */
const MAX_RESTART_RESUMES = Math.max(1, Number(process.env.WORKER_MAX_RESTART_RESUMES ?? 3));

/** Read/write the restart counter on a job's JSON payload (object payloads only). */
function restartCount(job: Pick<Job, "payload">): number {
  const p = job.payload;
  if (p && typeof p === "object" && !Array.isArray(p)) {
    const n = Number((p as Record<string, unknown>)._restarts);
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
}
function withRestartCount(job: Pick<Job, "payload">, n: number): Prisma.InputJsonValue | undefined {
  const p = job.payload;
  if (p == null) return { _restarts: n };
  if (typeof p === "object" && !Array.isArray(p)) return { ...(p as Record<string, unknown>), _restarts: n } as Prisma.InputJsonValue;
  return undefined; // non-object payload: leave it alone, counter stays 0
}

/**
 * Put an interrupted (RUNNING) job back on the queue WITHOUT charging it an
 * attempt, or fail it if it has already been interrupted too often. Used by
 * both `reapStuckJobs()` (crash / SIGKILL — found at the next boot) and the
 * graceful-shutdown drain (SIGTERM — done before exit). Returns the outcome.
 *
 * Safe because every handler is re-entrant on retry (the same property the
 * existing MAX_ATTEMPTS retry path relies on): PROVISION keeps vmid/password/
 * ip/port and skips the clone when the VM exists; RESIZE/DISK_EXPAND carry
 * their invoiceId and re-check; the control-panel/game ops are idempotent
 * shell. The restarted job's `step` tells the customer what happened.
 */
export async function requeueInterruptedJob(job: Job, why: string): Promise<"QUEUED" | "FAILED"> {
  const restarts = restartCount(job) + 1;
  if (restarts <= MAX_RESTART_RESUMES) {
    const payload = withRestartCount(job, restarts);
    // attempts-1 (floored at 0): the claim that got interrupted did not count.
    await db.$executeRaw`
      UPDATE "Job"
      SET status = 'QUEUED'::"JobStatus",
          attempts = GREATEST(attempts - 1, 0),
          error = NULL,
          step = ${`Resuming after ${why}…`},
          ${payload !== undefined ? Prisma.sql`payload = ${JSON.stringify(payload)}::jsonb,` : Prisma.empty}
          "updatedAt" = now()
      WHERE id = ${job.id} AND status = 'RUNNING'::"JobStatus"`;
    return "QUEUED";
  }
  await db.job.update({
    where: { id: job.id },
    data: { status: "FAILED", error: `Worker restarted mid-job ${restarts} times (${why})`, finishedAt: new Date() },
  });
  await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
  if (job.serverId) {
    const s = await db.server.findUnique({ where: { id: job.serverId } });
    if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
      await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
    }
    // Same IP-leak cleanup the runJob catch-path does — a PROVISION given up on
    // here would otherwise strand its dedicated IP + billable OVH vMAC forever
    // (audit 2026-08-01).
    if (job.type === "PROVISION") {
      await cleanupFailedProvision(job.serverId).catch((err) =>
        console.error(`[worker] cleanup failed provision (reap) ${job.id}`, err)
      );
      if (s) {
        await notifyProvisionFailed(s, "Worker restarted mid-job").catch((err) =>
          console.error(`[worker] notify provision failure (reap) ${job.id} failed`, err)
        );
      }
    }
  }
  return "FAILED";
}

/**
 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
 * killed worker leaves a job RUNNING forever, which permanently blocks the
 * server's "one in-flight job" guard and strands it in a transitional state.
 *
 * Runs exactly once, at startup, BEFORE `main()`'s loop (and its in-process
 * `active` map — see the concurrency comment there) starts claiming anything.
 * Any row still RUNNING at this point cannot belong to a job this process is
 * tracking (it hasn't claimed anything yet), so it can only be left over from
 * a prior process that died mid-job — never a false positive against a
 * legitimately-concurrent job.
 *
 * Since 2026-10-01 an interrupted job is RESUMED (requeued without burning an
 * attempt) rather than charged a failure — see requeueInterruptedJob. The
 * graceful-shutdown drain in main() normally leaves nothing for this to find;
 * it is the backstop for SIGKILL/OOM/power loss.
 */
export async function reapStuckJobs() {
  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
  for (const job of stuck) {
    const outcome = await requeueInterruptedJob(job, "worker restart");
    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${outcome}`);
  }
}


/** Pull newly-delivered provider IPs into every enabled node's pool + low-pool alert. */
async function dedicatedIpPoolSync(): Promise<void> {
  const nodes = await db.node.findMany({ where: { enabled: true }, select: { id: true } });
  let totalImported = 0;
  let totalCount = 0;
  for (const n of nodes) {
    if (!(await dedicatedIpProviderConfigured(n.id))) continue;
    const r = await syncDedicatedIpPool(n.id);
    totalImported += r.imported;
    totalCount += r.total;
  }
  if (totalImported > 0) console.log(`[worker] dedicated IP pool: imported ${totalImported}, total ${totalCount}`);
  // Low-pool alert, gated by the Settings toggle. (Auto-ordering IPs spends
  // real money via OVH and is intentionally left as a manual admin action.)
  const { getSettingBool, getSettingInt } = await import("../lib/settings");
  if (await getSettingBool("dedicated_ip_autoreplenish", false)) {
    // Count only what's actually available to a customer (excludes admin-
    // marked INTERNAL rows) — same eligibility as allocateDedicatedIp's
    // claim query, so this alert can't under-report a real shortage.
    const free = await freeDedicatedIpCount();
    const threshold = await getSettingInt("dedicated_ip_replenish_threshold", 2);
    if (free < threshold) {
      const recent = await db.notification.findFirst({
        where: { title: { contains: "Dedicated IP pool low" }, createdAt: { gt: new Date(Date.now() - 6 * 3600_000) } },
      });
      if (!recent) {
        const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
        await db.notification.createMany({
          data: admins.map((a) => ({
            userId: a.id,
            title: `Dedicated IP pool low (${free} free)`,
            body: `Free dedicated IPs (${free}) fell below the replenish threshold (${threshold}). Order more failover IPs from OVH, then the pool auto-imports on the next sync.`,
            href: "/admin/ips",
          })),
        });
      }
    }
  }
}

/**
 * Register every background sweep on the SweepRunner (worker/sweeps.ts).
 *
 * Each entry used to be an inline `if (Date.now() - lastX > interval)` block
 * at the top of the claim loop; intervals and groupings are preserved exactly
 * (a group that ran as one block with ordering requirements — e.g. partner
 * commissions AFTER the renewal sweeps — stays one sweep fn). Per-sweep
 * `timeoutMs` is the budget after which the runner stops waiting and logs an
 * overrun; see the runner's doc comment for why that is not a cancel.
 *
 * Exported for the load-test harness, which registers nothing but still
 * needs the list to document what else competes for the process.
 */
export function registerSweeps(runner: SweepRunner): void {
  const m = 60_000;
  const h = 60 * m;
  const add = (name: string, intervalMs: number, fn: () => Promise<unknown>, timeoutMs?: number) =>
    runner.register({ name, intervalMs, fn, timeoutMs });

  // Backstop for the first-month-free card/Stripe HOLD (lib/promo-redemption.ts)
  // and the checkout-coupon HOLD (lib/coupon-redemption.ts): reap RESERVED
  // redemptions whose payable window has lapsed. Cheap indexed deletes.
  add("promo-reservations", 2 * m, sweepExpiredReservations);
  add("coupon-reservations", 2 * m, sweepExpiredCouponReservations);

  // Weekly SEO audit + admin "run now" queue (self-throttled, see worker/seo-audit.ts). Fire-and-forget: a
  // multi-minute audit must never hold a sweep slot.
  add("seo-audit", m, async () => { void seoAuditTick(); });

  // Free-Minecraft health sweep (samples, crash/OOM events, watchdog, start queue, disk, trash). Self-paced to
  // every 2 min with its own in-flight guard (worker/freemc-health.ts); fire-and-forget.
  add("freemc-health", m, async () => { kickFreemcHealthSweep(); });

  // Bot re-classification, crawler access-log parsing, insights snapshot + alerts. Self-scheduling with its own
  // in-flight guard (worker/analytics.ts); fire-and-forget so DNS lookups / large log chunks never hold a sweep slot.
  add("analytics-insights", m, async () => { void analyticsInsightsTick().catch((e) => console.error("[analytics] insights tick error", e)); });

  // NX Labs catalog ingestion (lib/modsync): bounded slice every 5 min; overlap is prevented
  // inside modsyncTick + the DB claim on ModSyncProvider. Fire-and-forget so a long crawl never holds a sweep slot.
  add("modsync", 5 * m, async () => { void modsyncTick(); });

  // Game runtime truth (worker/game-runtime.ts): probes every running game server's real
  // service/port state and flags "VM up, game down" to the admins. Self-throttled and
  // non-blocking; the 1-min cadence just wakes the throttle.
  add("game-runtime", m, async () => gameRuntimeSweepTick());

  // Renewals, auto-charge, dunning; add-on product renewals; then partner
  // commissions AFTER the renewal sweeps so this pass picks up the invoices
  // they just created (idempotent). A card retry can take a while → 15 min budget.
  add("billing", 10 * m, async () => {
    try { await billingSweep(); } catch (e) { console.error("[billing] sweep error", e); }
    try { await productRenewalSweep(); } catch (e) { console.error("[product-billing] sweep error", e); }
    try { await reconcilePartnerCommissions(); } catch (e) { console.error("[partner-commission] sweep error", e); }
  }, 15 * m);
  // Pre-renewal "no card on file" + domain-expiry courtesy nudges — hourly is plenty.
  add("renewal-reminders", h, async () => {
    try { await renewalReminderSweep(); } catch (e) { console.error("[billing] renewal-reminder sweep error", e); }
    try { await domainExpiringWarningSweep(); } catch (e) { console.error("[billing] domain-expiry-warning sweep error", e); }
  });
  // Google Ads offline conversions — inert until the Ads API creds are set.
  add("google-ads", 15 * m, async () => {
    const { googleAdsConversionSweep } = await import("../lib/google-ads");
    const r = await googleAdsConversionSweep();
    if (r.uploaded || r.failed) console.log(`[google-ads] offline conversions: +${r.uploaded} uploaded, ${r.failed} failed, ${r.skipped} skipped`);
  });
  // Availability sampling — the dashboard's uptime figure is built from these (lib/uptime.ts).
  add("uptime", UPTIME_SWEEP_MS, sweepUptime);
  // Real SSH auth probe against RUNNING servers (bounded batch, cursor-paginated).
  // Each auth failure costs a full connect timeout, so budget generously.
  add("ssh-health", 15 * m, sshHealthSweep, 10 * m);
  // Power-state reconciliation (worker/vm-recovery.ts) — an actually-down
  // server is more urgent than a stale password, hence the shorter cadence.
  add("vm-recovery", 5 * m, vmRecoverySweep);
  // Auto-update opted-in game servers every ~6h (enqueues GAME_UPDATE jobs; bulk priority).
  add("game-update", 6 * h, gameUpdateSweep);
  // Minecraft server-software mirror (lib/mcjars): the 1-min cadence only wakes the
  // per-provider schedule in McMirrorProvider (6 h / backoff / run-now). Fire-and-forget
  // so a 30-min download pass never holds a SweepRunner slot; mcMirrorTick has its own
  // overlap guard plus a DB lease per provider.
  add("mc-mirror", m, async () => { void mcMirrorTick(); });
  // Fire due scheduled game-server restarts (~60s so an HH:MM schedule lands within a minute).
  add("game-schedule", m, gameScheduleSweep);
  // Player join/leave tracking via RCON (~60s); per-server try/catch inside.
  add("player-tracking", m, playerTrackingSweep, 5 * m);
  // Same for log-tailed families (Valheim) — see logPlayerTrackingSweep's doc comment.
  add("log-player-tracking", m, logPlayerTrackingSweep, 5 * m);
  // Geo-enrich recent visits (~90s) — external lookups, keep off the claim path.
  add("geo", 90_000, geoEnrichSweep);
  // Roll the raw Visit log into per-day VisitorDaily summaries (~15 min).
  add("visitor-rollup", 15 * m, visitorRollupSweep);
  // Scheduled customer backups (enqueues BACKUP_CREATE jobs; bulk priority).
  add("backup-schedule", 15 * m, scheduledBackupSweep);
  // Shared-hosting account provisioner + fast lane for "Check now / Go live".
  // No-op unless ENABLE_SHARED_HOSTING (see worker/hosting.ts).
  add("hosting", 30_000, async () => {
    await hostingProvisionSweep();
    await hostingDatabaseSweep();
    await hostingTaskSweep();
    const rechecked = await hostingHealthSweep({ onlyRequested: true });
    if (rechecked > 0) await hostingSslSweep();
    await hostingNodeHardenSweep().catch((e) => console.error("[hosting] node harden sweep error", e));
    await hostingNodeTelemetryDeploySweep().catch((e) => console.error("[hosting] telemetry deploy sweep error", e));
  }, 20 * m);
  // NxCloud: verify provisioning instances, mirror suspend/terminate, queued admin tasks.
  add("nxcloud", 30_000, async () => {
    await nxcloudProvisionSweep();
    await nxcloudTaskSweep();
  });
  // HTTPS for hosting accounts once the domain resolves to us — the SAFETY NET
  // for custom domains whose DNS lands later (certbot is --keep-until-expiring).
  add("hosting-ssl", 3 * m, async () => {
    await hostingSslSweep();
    await hostingUsageSweep();
  }, 10 * m);
  // Serve-verification + self-heal for every ACTIVE hosting account.
  add("hosting-health", 10 * m, () => hostingHealthSweep(), 10 * m);
  // Wildcard TLS cert for free subdomains — opt-in + inert unless configured.
  add("hosting-wildcard", 12 * h, hostingWildcardSweep, 20 * m);
  // SSL lifecycle: renew before expiry, reconcile ISSUING, age out PENDING; and
  // the post-cutover migration TLS pass sslSweep does NOT cover.
  add("ssl", 30 * m, async () => {
    try { await sslSweep(); } catch (e) { console.error("[ssl] sweep error", e); }
    try { await postCutoverTlsSweep(); } catch (e) { console.error("[migrate] post-cutover TLS sweep error", e); }
  }, 20 * m);
  // Monitoring alerts + abuse detection (~10 min).
  add("monitor", 10 * m, async () => {
    try { await monitorSweep(); } catch (e) { console.error("[monitor] sweep error", e); }
    try { await abuseSweep(); } catch (e) { console.error("[abuse] sweep error", e); }
  });
  // In-guest disk + memory sampling for every RUNNING VM (guest-agent) — one
  // Proxmox call per VM, so it gets its own slot rather than riding "monitor".
  add("guest-samples", 10 * m, async () => {
    try { await sampleServerDisks(); } catch (e) { console.error("[monitor] disk-sample sweep error", e); }
    try { await sampleServerMemory(); } catch (e) { console.error("[monitor] mem-sample sweep error", e); }
  }, 10 * m);
  // Platform component health → HealthSample + auto-incident state machine (/status).
  add("health-sample", 10 * m, sampleHealthSweep);
  // Prune TelemetryEvent rows past retention.
  add("telemetry-prune", 10 * m, telemetryPruneSweep);
  // Marketing Agent Phase 1: read-only discovery; NEVER posts anything.
  add("marketing", h, marketingDiscoverySweep, 10 * m);
  // Outreach campaigns (lib/outreach/campaign-core.ts): campaign-aware, paced by each campaign's own
  // interval/jitter/window/cap (persisted in the DB, so a restart neither bursts nor stalls) and
  // single-flight. Polled every 10 s so intervals under a minute work.
  add("outreach-queue", 10_000, processOutreachTick);
  // Reply / bounce / unsubscribe detection: READ-ONLY inbox scan every 10 min.
  add("outreach-scan", 10 * m, scanAllOutreachInboxes);
  // Partner free-server grants: 7-day / 1-day expiry notices + status bookkeeping (hourly).
  add("partner-grants", h, partnerGrantSweep);
  // SEO Opportunity Discovery (Search Console, weekly; first pull promptly on boot).
  add("seo", 7 * 24 * h, seoOpportunitySweep, 10 * m);
  // Re-engagement / onboarding mail sweeps — each INERT unless its setting is on.
  add("deploy-winback", 15 * m, deployWinbackSweep);
  add("dormant-winback", 15 * m, dormantWinbackSweep);
  add("onboarding-sequence", 15 * m, onboardingSequenceSweep);
  // Critical transactional email retry (default ON — resends a CRITICAL FAILED EmailLog).
  add("critical-email-retry", 12 * m, criticalEmailRetrySweep);
  // Ticket-reply / staff-DM email digests (the "one email per burst" coalescing flush).
  add("ticket-reply-digest", 20_000, ticketReplyDigestSweep);
  add("dm-reply-digest", 20_000, dmReplyDigestSweep);
  // Cold Email Engine: send queue (INERT unless cold_email_sending_enabled),
  // warmup maintenance, deliverability rollups, IMAP reply poller (creds-gated).
  add("coldemail-send", 2 * m, coldEmailSendSweep, 10 * m);
  add("coldemail-warmup", 15 * m, coldEmailWarmupSweep);
  add("coldemail-rollup", 10 * m, coldEmailRollupSweep);
  add("coldemail-inbox", 2 * m, coldEmailInboxPoll, 5 * m);
  // Dedicated-IP pool import for every enabled node + low-pool alert (~5 min).
  add("ip-pool-sync", 5 * m, dedicatedIpPoolSync);
}

/**
 * CONCURRENT JOB SCHEDULING — the core of this file's job-processing model.
 *
 * `active` tracks every job this process currently has RUNNING: job id -> its
 * in-flight promise plus the scheduler's view of it (lock key, node, user,
 * heavy/bulk flags). worker/scheduler.ts's `selectClaims` turns the QUEUED
 * candidates + `active` into an ordered list to attempt, enforcing:
 *
 *   1. Concurrency cap — at most `limits.concurrency` in flight. A slow job
 *      (a 20-minute PROVISION) occupies one slot for a long time and never
 *      blocks unrelated jobs.
 *   2. Per-server ordering — never two jobs for one serverId (or one
 *      platform-wide serverId-less type) at once, so a PROVISION and a later
 *      DELETE for the same server can't run concurrently or out of order.
 *   3. Priority — interactive (restart/power/config) ahead of normal
 *      (provision/delete/resize) ahead of bulk (backups/updates/SSL), with a
 *      cap on how many slots bulk may hold.
 *   4. Per-node caps — total and storage-heavy, so one node's Proxmox API/ZFS
 *      is never stampeded while the others sit idle.
 *   5. Fairness — a soft per-customer cap so one account can't monopolise the
 *      worker when others are waiting.
 *
 * WHY IN-PROCESS RATHER THAN A DB QUERY: there is exactly ONE worker process
 * for the whole platform (systemd unit `nxeon-worker`), and `reapStuckJobs()`
 * runs once at startup — before this loop claims anything — to clear out any
 * RUNNING row left over from a previous process. Given both, every row this
 * process ever sees with status RUNNING is a job THIS process itself claimed
 * via the CAS below, so `active` and "which lock keys have a RUNNING job in
 * the DB" are always the same set. It also closes a window a DB-only check
 * would have: two QUEUED jobs for the same server in the SAME batch would both
 * pass an "is there a RUNNING job for this server?" query — `selectClaims`
 * locks the key synchronously as it picks the first.
 *
 * The atomic CAS (`UPDATE … WHERE id AND status = QUEUED`, 1 row wins) is kept
 * — the scheduler only decides which rows to try it on. If this service is
 * ever split into multiple replicas, the in-process map stops being sufficient
 * and the per-server check must move to a DB-backed mechanism (e.g. a Postgres
 * advisory lock keyed on serverId like lib/job-guard.ts already uses on the
 * ENQUEUE side — a separate, complementary safeguard this scheduler does not
 * depend on).
 *
 * BACKGROUND SWEEPS no longer run inside this loop at all — see registerSweeps
 * + worker/sweeps.ts. The loop's only job is claiming jobs, so a slow sweep
 * can never again delay a claim.
 */
export type WorkerLoopOptions = {
  limits: SchedulerLimits;
  pollMs: number;
  /** Replace the real handlers (load-test harness). */
  handlers?: Record<string, (job: Job) => Promise<void>>;
  /** Replace the scheduler's selection (harness "legacy FIFO" baseline). */
  select?: typeof selectClaims;
  log?: (msg: string) => void;
};

export class WorkerLoop {
  readonly active = new Map<string, { promise: Promise<void>; entry: ActiveEntry; job: Job }>();
  private draining = false;
  private stopped = false;
  private loopDone: Promise<void> | null = null;
  private readonly runOne: (job: Job) => Promise<void>;

  constructor(private readonly opts: WorkerLoopOptions) {
    const h = opts.handlers;
    this.runOne = h ? (job) => runJob(job, h) : (job) => runJob(job);
  }

  get activeCount(): number {
    return this.active.size;
  }

  /** Run a claimed job, always freeing its `active` slot when it settles. */
  private launch(job: Job, candidate: Candidate) {
    const p = this.runOne(job)
      .catch((e) => {
        // runJob already catches and records handler errors internally; this
        // only guards against something truly unexpected (e.g. a DB error in
        // its own catch-path) so it can never become an unhandled rejection
        // that crashes the whole worker process out from under every other
        // concurrently-running job.
        console.error(`[worker] job ${job.id} threw outside its own error handling`, e);
      })
      .finally(() => {
        this.active.delete(job.id);
      });
    // The entry is built from the CANDIDATE (which carries server.nodeId/
    // userId from the claim query), not the bare Job row — otherwise every job
    // would count against "primary" and the per-node/per-user caps would be
    // meaningless.
    this.active.set(job.id, { promise: p, entry: activeEntryFor(candidate), job });
  }

  /**
   * One scheduling tick: read candidates, decide, CAS-claim, launch. Returns
   * how many jobs were started. Exported-ish (public) so the harness can drive
   * ticks deterministically.
   */
  async tick(): Promise<number> {
    const { limits } = this.opts;
    if (this.draining) return 0;
    const freeSlots = limits.concurrency - this.active.size;
    if (freeSlots <= 0) return 0;

    // Read candidates PER PRIORITY CLASS, oldest first within each. One plain
    // FIFO slice is not enough: the load test showed that with 150+ bulk rows
    // (a backup/update sweep's output) queued ahead of a burst, a batch of the
    // oldest N QUEUED rows contained only bulk-capped candidates and the
    // interactive jobs behind them were never even seen until the bulk work
    // drained — p50 queue wait for a restart was 2000s. Three indexed queries
    // ((status, createdAt) + a type filter) make every class visible every
    // tick regardless of how deep the other classes' backlog is.
    const take = claimBatchSize(limits);
    const include = { server: { select: { nodeId: true, userId: true } } } as const;
    const interactive = [...INTERACTIVE_TYPES] as JobType[];
    const bulk = [...BULK_TYPES] as JobType[];
    const [ci, cn, cb] = await Promise.all([
      db.job.findMany({ where: { status: "QUEUED", type: { in: interactive } }, orderBy: { createdAt: "asc" }, take, include }),
      db.job.findMany({ where: { status: "QUEUED", type: { notIn: [...interactive, ...bulk] } }, orderBy: { createdAt: "asc" }, take, include }),
      db.job.findMany({ where: { status: "QUEUED", type: { in: bulk } }, orderBy: { createdAt: "asc" }, take, include }),
    ]);
    const candidates = [...ci, ...cn, ...cb];
    if (candidates.length === 0) return 0;

    const decision = (this.opts.select ?? selectClaims)(
      candidates,
      [...this.active.values()].map((a) => a.entry),
      limits
    );

    let claimed = 0;
    for (const candidate of decision.claim) {
      if (this.draining) break;
      // Atomic claim: only the caller whose UPDATE matches the still-QUEUED row
      // wins. `startedAt` is set on the FIRST claim only (COALESCE) so a retry
      // keeps the original pickup time — queue wait is measured once.
      const won = await db.$executeRaw`
        UPDATE "Job"
        SET status = 'RUNNING'::"JobStatus",
            attempts = attempts + 1,
            "startedAt" = COALESCE("startedAt", now()),
            "updatedAt" = now()
        WHERE id = ${candidate.id} AND status = 'QUEUED'::"JobStatus"`;
      if (won !== 1) continue; // lost the race (retry path / another process) — move on
      const claimedJob = await db.job.findUnique({ where: { id: candidate.id } });
      if (!claimedJob) continue;
      claimed++;
      const waitMs = Date.now() - claimedJob.createdAt.getTime();
      (this.opts.log ?? console.log)(
        `[worker] job ${claimedJob.id} ${claimedJob.type} server=${claimedJob.serverId} claimed ` +
          `(${this.active.size + 1}/${limits.concurrency} slots busy, ${PRIORITY_LABEL[priorityOf(claimedJob.type)]}, ` +
          `waited ${Math.round(waitMs / 1000)}s)`
      );
      this.launch(claimedJob, candidate);
    }
    return claimed;
  }

  /** The forever loop. Resolves only after `stop()`. */
  start(): Promise<void> {
    if (this.loopDone) return this.loopDone;
    this.loopDone = (async () => {
      while (!this.stopped) {
        let claimed = 0;
        try {
          claimed = await this.tick();
        } catch (e) {
          console.error("[worker] loop error", e);
        }
        if (this.stopped) break;
        if (claimed === 0) {
          // Nothing new started this tick — queue empty, every slot busy, or
          // every candidate blocked by a cap. Poll again shortly; a slot
          // freeing is noticed within POLL_MS.
          await new Promise((r) => setTimeout(r, this.opts.pollMs));
        }
      }
    })();
    return this.loopDone;
  }

  /**
   * Graceful drain: stop claiming, wait up to `drainMs` for in-flight jobs to
   * finish on their own, then hand whatever is still running back to the
   * queue (attempt NOT charged) so the next process resumes it. Returns the
   * ids that were requeued.
   */
  async stop(drainMs: number): Promise<string[]> {
    this.draining = true;
    const deadline = Date.now() + drainMs;
    while (this.active.size > 0 && Date.now() < deadline) {
      const remaining = Math.max(0, deadline - Date.now());
      await Promise.race([
        Promise.allSettled([...this.active.values()].map((a) => a.promise)),
        new Promise((r) => setTimeout(r, Math.min(1000, remaining))),
      ]);
    }
    const requeued: string[] = [];
    for (const [id, a] of this.active) {
      const outcome = await requeueInterruptedJob(a.job, "worker restart").catch((e) => {
        console.error(`[worker] drain: could not requeue ${id}`, e);
        return "FAILED" as const;
      });
      if (outcome === "QUEUED") requeued.push(id);
      console.log(`[worker] drain: ${id} (${a.job.type}) still running -> ${outcome}`);
    }
    this.stopped = true;
    return requeued;
  }
}

/** How long a SIGTERM waits for in-flight jobs before requeueing them. Keep it
 *  under the unit's TimeoutStopSec (deploy/nxeon-worker.service sets 120s). */
const DRAIN_TIMEOUT_MS = Math.max(1000, Number(process.env.WORKER_DRAIN_TIMEOUT_MS ?? 60_000));
/** How many background sweeps may run simultaneously (alongside the job slots). */
const SWEEP_CONCURRENCY = Math.max(1, Number(process.env.WORKER_SWEEP_CONCURRENCY ?? 3));

async function main() {
  console.log("[worker] Nxeon provisioning worker starting");
  await reapStuckJobs();
  // Startup sync. A throw here would kill the worker outright, so it is
  // best-effort — but the "synced" line is only printed when it really was.
  // Announcing a sync that did not happen is the defect this file is fighting.
  if (!SANDBOX) {
    const natErr = await syncPortForwardsBestEffort("worker startup");
    console.log(natErr ? `[worker] port forwards NOT verified: ${natErr.message}` : "[worker] port forwards synced");
  }

  const limits = limitsFromEnv();
  console.log(
    `[worker] limits: concurrency=${limits.concurrency} bulkCap=${limits.bulkCap} perNode=${limits.perNodeCap} ` +
      `perNodeHeavy=${limits.perNodeHeavyCap} perUserSoft=${limits.perUserSoft} sweeps=${SWEEP_CONCURRENCY} drain=${DRAIN_TIMEOUT_MS}ms`
  );

  const sweeps = new SweepRunner({ maxConcurrent: SWEEP_CONCURRENCY });
  registerSweeps(sweeps);
  sweeps.start();

  const loop = new WorkerLoop({ limits, pollMs: POLL_MS });

  // Periodic one-line status so the journal shows what the process is doing
  // (slot occupancy, sweep overruns) without grepping per-job lines.
  const status = setInterval(() => {
    const over = sweeps.stats().filter((s) => s.overruns > 0).map((s) => `${s.name}×${s.overruns}`);
    console.log(
      `[worker] status: ${loop.activeCount}/${limits.concurrency} job slots, ${sweeps.activeCount} sweeps running` +
        (over.length ? `, overruns: ${over.join(" ")}` : "")
    );
  }, 5 * 60_000);
  status.unref();

  // Graceful shutdown (systemd stop/restart sends SIGTERM): stop claiming,
  // finish what can finish within the drain budget, hand the rest back to the
  // queue with the attempt uncharged, then exit 0 so systemd restarts cleanly.
  let shuttingDown = false;
  const shutdown = async (signal: string) => {
    if (shuttingDown) return;
    shuttingDown = true;
    console.log(`[worker] ${signal} received — draining (${loop.activeCount} in flight, up to ${Math.round(DRAIN_TIMEOUT_MS / 1000)}s)`);
    clearInterval(status);
    const [requeued, stillSweeping] = await Promise.all([
      loop.stop(DRAIN_TIMEOUT_MS),
      sweeps.stop(Math.min(DRAIN_TIMEOUT_MS, 30_000)),
    ]);
    console.log(
      `[worker] drained: ${requeued.length} job(s) requeued for the next process` +
        (stillSweeping.length ? `, sweeps still running at exit: ${stillSweeping.join(", ")}` : "")
    );
    await db.$disconnect().catch(() => {});
    process.exit(0);
  };
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
  process.on("SIGINT", () => void shutdown("SIGINT"));

  await loop.start();
}

// The harness imports this module for WorkerLoop/registerSweeps/runJob without
// wanting the real loop to start.
if (!process.env.NXEON_WORKER_NO_MAIN) main();

 *     ordered ahead of normal work (provision, delete, resize…) which is ahead
 *     of bulk work (backups, game updates, SSL, migrations). A restart queued
 *     behind twenty backups no longer waits for them.
 *  3. Bulk cap — bulk jobs may occupy at most `bulkCap` of the slots, so a
 *     backup-schedule or game-update sweep can never fill the worker and lock
 *     interactive actions out, no matter how many rows it enqueues.
 *  4. Per-node caps — a node's Proxmox API (pveproxy) and ZFS pool are the real
 *     bottleneck, not this process. `perNodeCap` bounds everything on one node;
 *     `perNodeHeavyCap` bounds the storage-heavy subset (clone, vzdump,
 *     restore, resize, destroy…) tighter, so a clone/start storm on one node is
 *     throttled while other nodes keep flowing.
 *  5. Fairness — a SOFT per-user cap: a customer already running `perUserSoft`
 *     jobs only gets more slots when nobody else is waiting for them, so one
 *     account bulk-ordering 30 servers can't monopolise the worker, but also
 *     isn't throttled when the queue is otherwise idle.
 *
 * Tunables come in via `SchedulerLimits` (worker/index.ts reads them from env
 * — see docs/DOCUMENTATION.md "Job lifecycle — the worker queue").
 */

import { adminOpsLockKey } from "../lib/admin-ops/types";
export type Priority = 0 | 1 | 2;

/** Customer is sitting on the button waiting for these. */
export const INTERACTIVE_TYPES: ReadonlySet<string> = new Set([
  "START", "STOP", "REBOOT", "GAME_POWER", "GAME_CONFIG", "PASSWORD_RESET",
  "SERVICE_ACTION", "CRON_SYNC", "WEBSITE_TOGGLE", "GAME_MOD_SYNC",
  "SNAPSHOT_CREATE", "SNAPSHOT_DELETE", "SNAPSHOT_ROLLBACK",
  "SYNC_FIREWALL", "SYNC_FORWARDS", "SYNC_GAME_DNS", "STAGING_CONTROL",
  "SUSPEND", "UNSUSPEND",
]);

/** Background / scheduled / long-running work nobody is watching a spinner for. */
export const BULK_TYPES: ReadonlySet<string> = new Set([
  "BACKUP_CREATE", "GAME_BACKUP", "GAME_UPDATE", "SSL_ISSUE", "MIGRATE",
  "CLAUDE_BUILD", "WEBSITE_SSL",
]);

/**
 * Jobs that saturate a node's storage/API while they run: a full-clone,
 * vzdump, restore, disk resize/expand, destroy, volume ops, snapshot ops.
 * Counted against `perNodeHeavyCap`.
 */
export const HEAVY_TYPES: ReadonlySet<string> = new Set([
  "PROVISION", "REINSTALL", "DELETE", "RESIZE", "DISK_EXPAND",
  "BACKUP_CREATE", "BACKUP_RESTORE", "SNAPSHOT_CREATE", "SNAPSHOT_ROLLBACK",
  "VOLUME_CREATE", "VOLUME_ATTACH", "VOLUME_DETACH", "VOLUME_DELETE",
  "MIGRATE", "GAME_REINSTALL",
]);

export function priorityOf(type: string): Priority {
  if (INTERACTIVE_TYPES.has(type)) return 0;
  if (BULK_TYPES.has(type)) return 2;
  return 1;
}

export const PRIORITY_LABEL: Record<Priority, "interactive" | "normal" | "bulk"> = {
  0: "interactive",
  1: "normal",
  2: "bulk",
};

/** The minimal shape of a QUEUED Job row the scheduler needs. */
export type Candidate = {
  id: string;
  type: string;
  serverId: string | null;
  createdAt: Date;
  /** `include: { server: { select: { nodeId, userId } } }` on the claim query. */
  server?: { nodeId: string | null; userId: string } | null;
};

/** What the loop remembers about each in-flight job. */
export type ActiveEntry = {
  lockKey: string;
  nodeKey: string | null;
  userKey: string | null;
  heavy: boolean;
  bulk: boolean;
};

export type SchedulerLimits = {
  /** Total in-flight jobs (WORKER_CONCURRENCY). */
  concurrency: number;
  /** Max bulk-priority jobs in flight at once. */
  bulkCap: number;
  /** Max jobs in flight per node. */
  perNodeCap: number;
  /** Max HEAVY_TYPES jobs in flight per node. */
  perNodeHeavyCap: number;
  /** Soft cap per customer — exceeded only when no other customer is waiting. */
  perUserSoft: number;
};

export const DEFAULT_LIMITS: SchedulerLimits = {
  concurrency: 16,
  bulkCap: 4,
  perNodeCap: 6,
  perNodeHeavyCap: 3,
  perUserSoft: 3,
};

/**
 * Read limits from the environment with the defaults above. Every value is
 * clamped to >= 1 so a typo can never wedge the worker at zero throughput.
 */
export function limitsFromEnv(env: Record<string, string | undefined> = process.env): SchedulerLimits {
  const n = (k: string, d: number) => {
    const v = Number(env[k]);
    return Number.isFinite(v) && v >= 1 ? Math.floor(v) : d;
  };
  const concurrency = n("WORKER_CONCURRENCY", DEFAULT_LIMITS.concurrency);
  return {
    concurrency,
    bulkCap: Math.min(concurrency, n("WORKER_BULK_CAP", Math.max(1, Math.floor(concurrency / 4)))),
    perNodeCap: n("WORKER_PER_NODE_CAP", DEFAULT_LIMITS.perNodeCap),
    perNodeHeavyCap: n("WORKER_PER_NODE_HEAVY_CAP", DEFAULT_LIMITS.perNodeHeavyCap),
    perUserSoft: n("WORKER_PER_USER_SOFT_CAP", DEFAULT_LIMITS.perUserSoft),
  };
}

/** A serverId-less job is keyed on its own type so two can't overlap. */
export function lockKeyFor(j: { id?: string; serverId: string | null; type: string; payload?: unknown }): string {
  // ADMIN_OPS jobs carry their own lock key (lib/admin-ops/types.ts) so two different ops don't serialize on `type:ADMIN_OPS`.
  return j.serverId ?? adminOpsLockKey({ id: j.id ?? "", type: j.type, serverId: j.serverId, payload: j.payload }) ?? `type:${j.type}`;
}

/** Node bucket a job counts against. A job with a server but no node row counts
 *  against "primary" (that is where connectionTarget/nodeFor send it too). */
export function nodeKeyFor(j: Candidate): string | null {
  if (!j.serverId) return null;
  return j.server?.nodeId ?? "primary";
}

export function activeEntryFor(j: Candidate): ActiveEntry {
  return {
    lockKey: lockKeyFor(j),
    nodeKey: nodeKeyFor(j),
    userKey: j.server?.userId ?? null,
    heavy: HEAVY_TYPES.has(j.type),
    bulk: priorityOf(j.type) === 2,
  };
}

class Tally {
  locked = new Set<string>();
  perNode = new Map<string, number>();
  perNodeHeavy = new Map<string, number>();
  perUser = new Map<string, number>();
  bulk = 0;
  total = 0;

  constructor(active: Iterable<ActiveEntry>) {
    for (const a of active) this.add(a);
  }

  add(a: ActiveEntry) {
    this.total++;
    this.locked.add(a.lockKey);
    if (a.nodeKey) {
      this.perNode.set(a.nodeKey, (this.perNode.get(a.nodeKey) ?? 0) + 1);
      if (a.heavy) this.perNodeHeavy.set(a.nodeKey, (this.perNodeHeavy.get(a.nodeKey) ?? 0) + 1);
    }
    if (a.userKey) this.perUser.set(a.userKey, (this.perUser.get(a.userKey) ?? 0) + 1);
    if (a.bulk) this.bulk++;
  }

  /** Hard caps only — the ones that are never relaxed. */
  hardBlocked(e: ActiveEntry, lim: SchedulerLimits): string | null {
    if (this.total >= lim.concurrency) return "concurrency";
    if (this.locked.has(e.lockKey)) return "lock";
    if (e.bulk && this.bulk >= lim.bulkCap) return "bulk-cap";
    if (e.nodeKey) {
      if ((this.perNode.get(e.nodeKey) ?? 0) >= lim.perNodeCap) return "node-cap";
      if (e.heavy && (this.perNodeHeavy.get(e.nodeKey) ?? 0) >= lim.perNodeHeavyCap) return "node-heavy-cap";
    }
    return null;
  }

  userCount(userKey: string | null): number {
    return userKey ? (this.perUser.get(userKey) ?? 0) : 0;
  }
}

export type Decision = {
  /** Candidates to attempt the CAS on, in order. */
  claim: Candidate[];
  /** Why each skipped candidate was skipped (for `--verbose` harness output / debugging). */
  skipped: Array<{ id: string; reason: string }>;
};

/**
 * Decide which candidates to claim this tick.
 *
 * `candidates` is whatever the loop read (QUEUED, oldest first); `active` is
 * everything in flight. The result honours every cap as if each claim in
 * `claim` succeeds — the caller's CAS may still lose a row (skip it; the
 * tally is then merely conservative for one tick).
 */
export function selectClaims(
  candidates: Candidate[],
  active: Iterable<ActiveEntry>,
  lim: SchedulerLimits
): Decision {
  const tally = new Tally(active);
  const claim: Candidate[] = [];
  const skipped: Array<{ id: string; reason: string }> = [];
  if (tally.total >= lim.concurrency) {
    return { claim, skipped: candidates.map((c) => ({ id: c.id, reason: "concurrency" })) };
  }

  // Order: priority class first, then (within a class) customers with fewer
  // jobs already running go first — that is the round-robin half of fairness
  // — then FIFO. Stable sort keeps FIFO within ties.
  const ordered = candidates
    .map((c, i) => ({ c, i, p: priorityOf(c.type), u: tally.userCount(c.server?.userId ?? null) }))
    .sort((a, b) => a.p - b.p || a.u - b.u || a.c.createdAt.getTime() - b.c.createdAt.getTime() || a.i - b.i)
    .map((x) => x.c);

  // Pass 1: everything, honouring the SOFT per-user cap. Candidates deferred
  // only by that cap are kept aside.
  const deferred: Candidate[] = [];
  const sameTickLocks = new Set<string>();
  for (const c of ordered) {
    if (tally.total >= lim.concurrency) { skipped.push({ id: c.id, reason: "concurrency" }); continue; }
    const e = activeEntryFor(c);
    // Two QUEUED jobs for one server in the same batch: the first one claimed
    // locks the key synchronously, so the second is skipped here, not raced.
    if (sameTickLocks.has(e.lockKey)) { skipped.push({ id: c.id, reason: "lock" }); continue; }
    const hard = tally.hardBlocked(e, lim);
    if (hard) { skipped.push({ id: c.id, reason: hard }); continue; }
    if (tally.userCount(e.userKey) >= lim.perUserSoft) { deferred.push(c); continue; }
    tally.add(e);
    sameTickLocks.add(e.lockKey);
    claim.push(c);
  }

  // Pass 2: slots still free and nobody else could use them → relax the soft
  // cap for the deferred candidates (hard caps still apply).
  for (const c of deferred) {
    if (tally.total >= lim.concurrency) { skipped.push({ id: c.id, reason: "concurrency" }); continue; }
    const e = activeEntryFor(c);
    if (sameTickLocks.has(e.lockKey)) { skipped.push({ id: c.id, reason: "lock" }); continue; }
    const hard = tally.hardBlocked(e, lim);
    if (hard) { skipped.push({ id: c.id, reason: hard }); continue; }
    tally.add(e);
    sameTickLocks.add(e.lockKey);
    claim.push(c);
  }

  return { claim, skipped };
}

/**
 * How many candidate rows the loop should read per tick. More than the free
 * slots because many may be filtered (lock/node/bulk caps), and more than the
 * total concurrency so a long run of blocked bulk rows can't hide a runnable
 * interactive one further down the FIFO.
 */
export function claimBatchSize(lim: SchedulerLimits): number {
  return Math.max(lim.concurrency * 8, 64);
}

