async function appendLog(moveId: string, phase: string, msg: string): Promise<void> {
  console.log(`[vm-move] ${moveId} ${phase}: ${msg}`);
  const row = await db.vmMove.findUnique({ where: { id: moveId }, select: { log: true } });
  const log = ((row?.log as MoveLogLine[] | null) ?? []).slice(-400);
  log.push({ at: new Date().toISOString(), phase, msg });
  await db.vmMove.update({ where: { id: moveId }, data: { log: log as unknown as Prisma.InputJsonValue } }).catch(() => {});
}

async function saveCheckpoints(moveId: string, patch: Partial<MoveCheckpoints>, phase?: MovePhase): Promise<MoveCheckpoints> {
  const row = await db.vmMove.findUnique({ where: { id: moveId } });
  const next = { ...cpOf(row!), ...patch };
  await db.vmMove.update({
    where: { id: moveId },
    data: { checkpoints: next as unknown as Prisma.InputJsonValue, ...(phase ? { phase } : {}) },
  });
  return next;
}

