async function vmRunning(conn: PveClient, vmid: number): Promise<boolean | null> {
  try {
    const s = await conn.vmStatus(vmid);
    return s?.status === "running";
  } catch (e) {
    if (isVmAbsentError(e, vmid)) return null;
    throw e;
  }
}

async function stopVm(conn: PveClient, vmid: number): Promise<void> {
  const running = await vmRunning(conn, vmid);
  if (!running) return;
  try {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/shutdown`, { timeout: SHUTDOWN_TIMEOUT_S });
    await conn.waitForTask(upid, (SHUTDOWN_TIMEOUT_S + 30) * 1000);
  } catch {
    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
    await conn.waitForTask(upid, 120_000);
  }
  if (await vmRunning(conn, vmid)) throw new Error(`vm ${vmid} on ${conn.node} is still running after shutdown+stop`);
}

async function startVm(conn: PveClient, vmid: number): Promise<void> {
  if (await vmRunning(conn, vmid)) return;
  const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
  await conn.waitForTask(upid, 180_000);
}

function destroyHost(conn: PveClient): VmDestroyHost {
  return {
    probe: async (id) => {
      try {
        await conn.vmStatus(id);
        return "present";
      } catch (e) {
        return isVmAbsentError(e, id) ? "absent" : "unknown";
      }
    },
    stop: async (id) => {
      const upid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
      await conn.waitForTask(upid);
    },
    destroy: async (id) => {
      const upid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, { "destroy-unreferenced-disks": 1, purge: 1 });
      await conn.waitForTask(upid, 600_000);
    },
  };
}

async function writeSnippet(node: MoveNode, storage: string, filename: string, content: string): Promise<void> {
  if (node.isPrimary) await writeFile(`${SNIPPET_DIR}/${filename}`, content, "utf8");
  else await agentWriteSnippet(node, storage, filename, content);
}
