type Ctx = {
  job: Job;
  move: MoveRow;
  plan: MovePlan;
  source: MoveNode;
  target: MoveNode;
  srcConn: PveClient;
  tgtConn: PveClient;
  srcZfs: ZfsHost;
  tgtZfs: ZfsHost;
  dedicated: boolean;
  progress: Progress;
};

async function transfer(ctx: Ctx, snap: string, from: string | null, label: string): Promise<void> {
  const { plan, srcZfs, tgtZfs } = ctx;
  const total = plan.sourceUsedBytes || 1;
  let lastReport = 0;
  const stream = await srcZfs.sendStream(plan.sourceDataset, snap, from);
  const m = meter((bytes) => {
    const now = Date.now();
    if (now - lastReport > 5000) {
      lastReport = now;
      // Compressed bytes on the wire vs the uncompressed `used` figure —
      // a rough but monotonic indicator, good enough for a progress bar.
      const pct = Math.min(99, Math.round((bytes / total) * 100));
      void ctx.progress(ctx.job.id, pct, `${label}: ${(bytes / 2 ** 30).toFixed(2)} GB sent`);
    }
  });
  stream.pipe(m);
  stream.on("error", (e) => m.destroy(e));
  try {
    await tgtZfs.recv(plan.targetDataset, m);
  } catch (e) {
    stream.destroy(); // stop the source-side zfs send / ssh / agent stream
    throw e;
  }
}

/** Must match worker/index.ts's MAX_ATTEMPTS — the job's attempts counter is
 *  incremented at claim time, so on the last permitted attempt a failure
 *  that would otherwise leave the VmMove row RUNNING forever is finalised. */
const MOVE_MAX_ATTEMPTS = 3;

async function runPhase(ctx: Ctx, phase: MovePhase): Promise<void> {
  const { move, plan, source, target, srcConn, tgtConn, srcZfs, tgtZfs } = ctx;
  const log = (msg: string) => appendLog(move.id, phase, msg);
  await ctx.progress(ctx.job.id, 0, `${phase}`);

  switch (phase) {
    case "SNAPSHOT_LIVE": {
      const name = liveSnapshotName(move.id);
      const existing: any[] = await srcConn.get(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/snapshot`).catch(() => []);
      if (!(existing ?? []).some((s) => s?.name === name)) {
        // vmstate=0: disk-only. With the guest agent enabled Proxmox fs-freezes
        // the guest for the instant of the snapshot, so the full pass is
        // filesystem-consistent, not merely crash-consistent.
        const upid = await srcConn.post(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/snapshot`, {
          snapname: name,
          vmstate: 0,
          description: `Nxeon VM move ${move.id} → ${target.name} (live pass)`,
        });
        await srcConn.waitForTask(upid, 300_000);
      }
      await saveCheckpoints(move.id, { liveSnapshotName: name });
      await log(`consistent snapshot ${name} on ${source.name}`);
      return;
    }
    case "SEND_FULL": {
      const cp = cpOf(move);
      const info = await tgtZfs.dataset(plan.targetDataset);
      if (info.exists && info.snapshots.includes(cp.liveSnapshotName!)) {
        await log(`target already holds ${plan.targetDataset}@${cp.liveSnapshotName} — skipping the full send`);
      } else {
        if (info.exists) {
          // A partial receive from an interrupted attempt — zfs leaves no usable
          // state behind; start the dataset over.
          await tgtZfs.destroyDataset(plan.targetDataset);
          await log(`removed partial ${plan.targetDataset} from an earlier attempt`);
        }
        const t0 = Date.now();
        await transfer(ctx, cp.liveSnapshotName!, null, "Full copy");
        await log(`full stream done in ${Math.round((Date.now() - t0) / 1000)}s (${(plan.sourceUsedBytes / 2 ** 30).toFixed(1)} GB used on source)`);
      }
      await saveCheckpoints(move.id, { fullSentAt: new Date().toISOString() });
      return;
    }
    case "STOP_SOURCE": {
      const wasRunning = await vmRunning(srcConn, plan.sourceVmid);
      await stopVm(srcConn, plan.sourceVmid);
      // STOPPED here keeps vmRecoverySweep from restarting the source (it only

      // STOPPED here keeps vmRecoverySweep from restarting the source (it only
      // looks at RUNNING rows) and is also the truth: the customer's server is
      // off for the duration of the dark window.
      await db.server.update({ where: { id: move.serverId }, data: { status: "STOPPED" } });
      await saveCheckpoints(move.id, { sourceStoppedAt: new Date().toISOString(), previousIpAddress: (await db.server.findUnique({ where: { id: move.serverId }, select: { ipAddress: true } }))?.ipAddress ?? null });
      await log(`source vm ${plan.sourceVmid} stopped (was ${wasRunning ? "running" : "already stopped"}) — dark window opened`);
      return;
    }
    case "SEND_INCREMENTAL": {
      const cp = cpOf(move);
      const name = cp.incrementalSnapshotName ?? incrementalSnapshotName(move.id);
      const src = await srcZfs.dataset(plan.sourceDataset);
      if (!(src.exists && src.snapshots.includes(name))) await srcZfs.snapshot(plan.sourceDataset, name);
      await saveCheckpoints(move.id, { incrementalSnapshotName: name });
      const tgt = await tgtZfs.dataset(plan.targetDataset);
      if (tgt.exists && tgt.snapshots.includes(name)) {
        await log(`target already holds @${name} — skipping incremental`);
      } else {
        const t0 = Date.now();
        await transfer(ctx, name, cp.liveSnapshotName!, "Final sync");
        await log(`incremental stream done in ${Math.round((Date.now() - t0) / 1000)}s`);
      }
      await saveCheckpoints(move.id, { incrementalSentAt: new Date().toISOString() });
      return;
    }
    case "CREATE_TARGET": {
      const cp = cpOf(move);
      const server = await loadMoveServer(move.serverId);
      if (!server) throw new Error("server row vanished mid-move");
      const srcCfg = await srcConn.get(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`);
      const disk = parseScsi0(String(srcCfg?.scsi0 ?? ""));
      if (!disk) throw new Error("source scsi0 unreadable at CREATE_TARGET");

      // Move-safe vendor snippet first — the config below references it.
      const snippetName = `nxeon-${plan.targetVmid}.yaml`;
      await writeSnippet(target, plan.targetSnippetStorage, snippetName, moveSafeVendorSnippet());
      await saveCheckpoints(move.id, { targetSnippetWritten: true });

      let network: Parameters<typeof buildTargetConfig>[0]["network"];
      let targetPrivateIp: string | undefined;
      if (plan.addressing.kind === "DEDICATED") {
        // The Virtual MAC on the target server is created in MOVE_IP (it needs
        // the IP routed there first). Boot config gets a placeholder MAC that
        // MOVE_IP rewrites before START_TARGET — never start with it.
        network = { kind: "DEDICATED", address: plan.addressing.address, gateway: plan.addressing.targetGateway, virtualMac: cp.targetVirtualMac ?? "02:00:00:00:00:00", bridge: "vmbr0" };
      } else {
        // Reserve a private IP in the target's /24 (in-process reservation,
        // see lib/ipam.ts) — written onto the Server row only at COMMIT.
        targetPrivateIp = (cp as any).targetPrivateIp ?? (await allocateIp(target.id));
        network = { kind: "NAT", privateIp: targetPrivateIp!, gateway: plan.addressing.targetGateway, mac: macFromNet0(srcCfg?.net0), bridge: plan.targetBridge };
      }
      const cfg = buildTargetConfig({
        targetVmid: plan.targetVmid,
        carried: plan.carriedConfig,
        disk,
        targetStorage: plan.targetStorage,
        snippetStorage: plan.targetSnippetStorage,
        network,
        cipassword: serverRootPassword(server),
      });
      const exists = await vmRunning(tgtConn, plan.targetVmid);
      if (exists === null) {
        const upid = await tgtConn.post(`/nodes/${tgtConn.node}/qemu`, cfg);
        await tgtConn.waitForTask(upid, 120_000);
      } else {
        await log(`target vm ${plan.targetVmid} already exists — reusing`);
      }
      // The received dataset still carries this engine's two snapshots; the
      // target VM must start clean (Proxmox knows nothing about them).
      for (const s of [cp.liveSnapshotName, cp.incrementalSnapshotName]) if (s) await tgtZfs.deleteSnapshot(plan.targetDataset, s).catch(() => {});
      await saveCheckpoints(move.id, { targetVmCreated: true, ...(targetPrivateIp ? ({ targetPrivateIp } as any) : {}) });
      await log(`target vm ${plan.targetVmid} created on ${target.name} (${network.kind}${targetPrivateIp ? ` ${targetPrivateIp}` : ""})`);
      return;
    }
    case "MOVE_IP": {
      if (plan.addressing.kind !== "DEDICATED") return;
      const a = plan.addressing;
      const taskId = await ovhMoveIp(a.address, a.targetService);
      await saveCheckpoints(move.id, { ipMovedAt: new Date().toISOString(), ...(taskId !== null ? { ipMoveTaskId: taskId } : {}) });
      await log(`OVH routed ${a.address} → ${a.targetService}${taskId !== null ? ` (task ${taskId})` : " (already there)"}`);
      const mac = await ovhEnsureVirtualMac(a.targetService, a.address, `nxeon-${plan.targetVmid}`);
      await tgtConn.post(`/nodes/${tgtConn.node}/qemu/${plan.targetVmid}/config`, {
        net0: `virtio=${mac},bridge=vmbr0`,
        ipconfig0: `ip=${a.address}/32,gw=${a.targetGateway}`,
      });
      await saveCheckpoints(move.id, { targetVirtualMac: mac });
      await log(`virtual MAC ${mac} bound on ${a.targetService}; target net0 updated`);
      return;
    }
    case "START_TARGET": {
      await startVm(tgtConn, plan.targetVmid);
      await saveCheckpoints(move.id, { targetStartedAt: new Date().toISOString() });
      await ctx.progress(ctx.job.id, 90, "Waiting for the guest agent…");
      const agentOk = await waitForGuestAgent(tgtConn, tgtConn.node, plan.targetVmid, 240_000);
      await log(agentOk ? "guest agent answered on the target" : "guest agent did NOT answer within 240s");
      // External reachability — exactly what the customer will dial.
      let sshOk = false;
      let sshDetail = "";
      if (plan.addressing.kind === "DEDICATED") {
        const r = await checkSshReachable(plan.addressing.address, 22, { timeoutMs: 180_000 });
        sshOk = r.ok;
        sshDetail = `${plan.addressing.address}:22 ${r.ok ? "answered" : `no SSH banner (${r.error ?? "timeout"})`}`;
      } else {
        const cp = cpOf(move);
        const privateIp = (cp as any).targetPrivateIp as string | undefined;
        // NAT rules for the new address are installed at COMMIT (they key off
        // Server.nodeId/ipAddress); before that, probe the guest from the
        // target node itself is not possible from here, so verify via the
        // agent + a TCP probe once COMMIT has synced NAT (see COMMIT).
        sshOk = agentOk;
        sshDetail = `NAT guest ${privateIp ?? "?"} — external SSH verified after COMMIT's NAT sync`;
      }
      if (!agentOk && !sshOk) throw new Error(`target vm ${plan.targetVmid} started but neither the guest agent nor SSH answered (${sshDetail})`);
      await saveCheckpoints(move.id, { targetVerified: true });
      await log(`target verified: ${sshDetail}`);
      return;
    }
    case "COMMIT": {
      const cp = cpOf(move);
      const server = await loadMoveServer(move.serverId);
      if (!server) throw new Error("server row vanished mid-move");
      const targetPrivateIp = (cp as any).targetPrivateIp as string | undefined;
      const addressChanged = plan.addressing.kind === "NAT";
      await db.$transaction(async (tx) => {
        await tx.server.update({
          where: { id: move.serverId },
          data: {
            nodeId: target.id,
            vmid: plan.targetVmid,
            status: "RUNNING",
            ...(plan.addressing.kind === "NAT" && targetPrivateIp ? { ipAddress: targetPrivateIp } : {}),
          },
        });
        if (plan.addressing.kind === "DEDICATED") {
          await tx.dedicatedIp.updateMany({
            where: { address: plan.addressing.address },
            data: { nodeId: target.id, virtualMac: cp.targetVirtualMac ?? undefined },
          });
        }
        await tx.vmMove.update({
          where: { id: move.id },
          data: { addressChanged, keepSourceUntil: new Date(Date.now() + KEEP_SOURCE_DAYS * 86_400_000) },
        });
      });
      await saveCheckpoints(move.id, { committedAt: new Date().toISOString() });
      await log(`DB cutover: node ${source.name} → ${target.name}, vmid ${plan.sourceVmid} → ${plan.targetVmid}${targetPrivateIp ? `, private IP → ${targetPrivateIp}` : ""}`);

      // Source must never come back on its own (a node reboot runs onboot
      // guests) — and is visibly marked as a moved leftover.
      try {
        const srcCfg = await srcConn.get(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`);
        const tags = String(srcCfg?.tags ?? "").split(";").filter(Boolean).filter((t) => t !== "nxeon-moved");
        tags.push("nxeon-moved");
        await srcConn.post(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`, { onboot: 0, tags: tags.join(";") });
        await saveCheckpoints(move.id, { sourceOnbootDisabled: true });
      } catch (e: any) {
        await log(`WARNING: could not set onboot=0 on the source vm: ${e?.message ?? e} — set it by hand before the next source-node reboot`);
      }

      // NAT on BOTH nodes: the source chain loses this server's rules (its
      // nodeId changed), the target chain gains them. Dedicated-IP servers
      // have no rules. Reported, never swallowed.
      if (!SANDBOX) {
        const natErr = await syncPortForwardsBestEffort(`vm move ${server.hostname}`);
        await log(natErr ? `NAT sync reported: ${natErr.message}` : "NAT chains reconciled on every node");
        if (plan.addressing.kind === "NAT" && server.sshPort) {
          const r = await checkSshReachable(target.publicIp, server.sshPort, { timeoutMs: 120_000 });
          await log(`external SSH ${target.publicIp}:${server.sshPort} ${r.ok ? "answered" : `did not answer (${r.error ?? "timeout"})`}`);
        }
      }
      if (server.subdomain) {
        await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
        await log(`queued SYNC_GAME_DNS for ${server.subdomain}`);
      }

      // Customer notice — ONLY when the address really changed.
      if (addressChanged) {
        const title = `${server.hostname}: new connection address`;
        const body =
          `Your server ${server.hostname} now runs on upgraded hardware and has a new public address: ${target.publicIp}. ` +
          `Your SSH port${server.sshPort ? ` (${server.sshPort})` : ""} and any game ports are unchanged${server.subdomain ? `, and ${server.subdomain}.play.nxeon.cloud already points at the new address` : ""}. ` +
          `Please update any saved connections that use the old IP (${source.publicIp}).`;
        await db.notification.create({ data: { userId: server.userId, title, body, href: `/dashboard/servers/${server.id}` } }).catch(() => {});
        if (server.user?.email) {
          await sendMail({
            to: server.user.email,
            subject: title,
            html: `<p>${body}</p><p>Nothing else about your server changed — same data, same plan, same root password.</p>`,
            text: body,
            userId: server.userId,
          }).catch((e) => console.error("[vm-move] customer email failed", e));
        }
      } else {
        await db.notification
          .create({
            data: {
              userId: server.userId,
              title: `${server.hostname} was moved to upgraded hardware`,
              body: "A short restart happened during the move. Your IP address, ports and data are unchanged.",
              href: `/dashboard/servers/${server.id}`,
            },
          })
          .catch(() => {});
      }

      await db.auditLog.create({
        data: {
          userId: move.requestedById ?? null,
          action: "server.vm_move",
          category: "server",
          target: server.hostname,
          detail: `${source.name}(vmid ${plan.sourceVmid}) → ${target.name}(vmid ${plan.targetVmid}) ${plan.addressing.kind}${addressChanged ? " address-changed" : ""} move=${move.id}`,
        },
      });
      await db.vmMove.update({ where: { id: move.id }, data: { status: "DONE", phase: "DONE", finishedAt: new Date() } });
      await log(`move complete; source vm ${plan.sourceVmid} kept STOPPED on ${source.name} until ${new Date(Date.now() + KEEP_SOURCE_DAYS * 86_400_000).toISOString().slice(0, 10)}`);
      return;
    }
    case "PREFLIGHT":
    case "DONE":
      return;
  }
}

// ---------------------------------------------------------------------------
// Rollback
// ---------------------------------------------------------------------------

async function rollback(ctx: Ctx, why: string): Promise<{ ok: boolean; errors: string[] }> {
  const { move, plan, source, target, srcConn, tgtConn, tgtZfs } = ctx;
  const cp = cpOf(move);
  const steps = rollbackSteps(cp, { dedicated: ctx.dedicated });
  const done: string[] = [];
  const errors: string[] = [];
  await appendLog(move.id, "ROLLBACK", `starting rollback (${why}); steps: ${steps.join(" → ")}`);
  await saveCheckpoints(move.id, { rollback: { startedAt: new Date().toISOString(), steps: [], errors: [] } });
  for (const step of steps) {
    try {
      switch (step) {
        case "MOVE_IP_BACK": {
          if (plan.addressing.kind !== "DEDICATED") break;
          const a = plan.addressing;
          await ovhReleaseVirtualMac(a.targetService, a.address, cp.targetVirtualMac ?? null);
          await ovhMoveIp(a.address, a.sourceService);
          // The source's Virtual MAC object may or may not have survived the
          // move; make sure one exists and that the source VM carries it.
          const mac = await ovhEnsureVirtualMac(a.sourceService, a.address, `nxeon-${plan.sourceVmid}`);
          await srcConn.post(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/config`, { net0: `virtio=${mac},bridge=vmbr0`, ipconfig0: `ip=${a.address}/32,gw=${a.sourceGateway}` });
          await db.dedicatedIp.updateMany({ where: { address: a.address }, data: { nodeId: source.id, virtualMac: mac } });
          break;
        }
        case "STOP_TARGET":
          await stopVm(tgtConn, plan.targetVmid);
          break;
        case "DESTROY_TARGET_VM":
          await destroyVmIdempotent(destroyHost(tgtConn), plan.targetVmid);
          break;
        case "DESTROY_TARGET_DATASET":
          await tgtZfs.destroyDataset(plan.targetDataset);
          break;
        case "DELETE_TARGET_SNIPPET":
          await deleteSnippet(target, plan.targetSnippetStorage, `nxeon-${plan.targetVmid}.yaml`);
          break;
        case "DELETE_SOURCE_INCREMENTAL_SNAPSHOT":
          if (cp.incrementalSnapshotName) await ctx.srcZfs.deleteSnapshot(plan.sourceDataset, cp.incrementalSnapshotName);
          break;
        case "START_SOURCE":
          await startVm(srcConn, plan.sourceVmid);
          break;
        case "RESTORE_DB_STATUS":
          await db.server.update({ where: { id: move.serverId }, data: { status: "RUNNING" } });
          break;
      }
      done.push(step);
    } catch (e: any) {
      errors.push(`${step}: ${String(e?.message ?? e).slice(0, 300)}`);
    }
  }
  // The live-pass Proxmox snapshot is harmless but pointless now.
  if (cp.liveSnapshotName) {
    try {
      const upid = await srcConn.del(`/nodes/${srcConn.node}/qemu/${plan.sourceVmid}/snapshot/${cp.liveSnapshotName}`);
      await srcConn.waitForTask(upid, 120_000);
    } catch {
      /* best-effort */
    }
  }
  await saveCheckpoints(move.id, { rollback: { startedAt: cp.rollback?.startedAt ?? new Date().toISOString(), finishedAt: new Date().toISOString(), steps: done, errors } });
  await appendLog(move.id, "ROLLBACK", errors.length ? `finished WITH ERRORS: ${errors.join(" | ")}` : `finished cleanly (${done.join(", ")})`);
  return { ok: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// Job entry points
// ---------------------------------------------------------------------------

/** VM_MOVE handler. `progress` is worker/index.ts's reportJobProgress. */
export async function vmMoveJob(job: Job, progress: Progress): Promise<void> {
  const payload = (job.payload ?? {}) as Partial<VmMoveJobPayload>;
  if (!payload.vmMoveId) throw new Error("VM_MOVE job has no vmMoveId");
  let move = await db.vmMove.findUnique({ where: { id: payload.vmMoveId } });
  if (!move) throw new Error(`VmMove ${payload.vmMoveId} not found`);
  if (move.status === "DONE" || move.status === "CLEANED") return;
  if (move.status === "ROLLED_BACK" || move.status === "FAILED") {
    // Terminal: say so on every retry so the job ends FAILED with the reason,
    // rather than quietly DONE.
    throw new Error(move.error ?? `move is ${move.status}`);
  }
  if (SANDBOX) {
    await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error: "VM moves are not simulated in sandbox mode", finishedAt: new Date() } });
    throw new Error("VM moves are not simulated in sandbox mode");
  }

  // ---- PREFLIGHT (always re-run on a fresh move; dry runs stop here) --------------
  if (!move.plan || move.phase === "PREFLIGHT") {
    await progress(job.id, 2, "Preflight…");
    const plan = await buildMovePlan({ serverId: move.serverId, targetNodeId: move.targetNodeId, allowDropSnapshots: !!(move.checkpoints as any)?.allowDropSnapshots });
    await db.vmMove.update({
      where: { id: move.id },
      data: {
        plan: plan as unknown as Prisma.InputJsonValue,
        targetVmid: plan.targetVmid || move.targetVmid,
        sourceVmid: plan.sourceVmid || move.sourceVmid,
        sourceNodeId: plan.sourceNodeId,
      },
    });
    const failed = plan.checks.filter((c) => !c.ok && c.blocking);
    if (move.dryRun) {
      await db.vmMove.update({ where: { id: move.id }, data: { status: "PLANNED", phase: "PREFLIGHT", finishedAt: new Date(), error: failed.length ? `preflight: ${failed.map((c) => c.detail).join("; ")}` : null } });
      await appendLog(move.id, "PREFLIGHT", `dry run: ${plan.ok ? "all blocking checks passed" : `${failed.length} blocking check(s) failed`}`);
      return;
    }
    if (!plan.ok) {
      const error = `preflight failed: ${failed.map((c) => `[${c.id}] ${c.detail}`).join("; ")}`.slice(0, 1900);
      await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error, finishedAt: new Date() } });
      await appendLog(move.id, "PREFLIGHT", error);
      throw new Error(error);
    }
    move = await db.vmMove.update({ where: { id: move.id }, data: { status: "RUNNING", phase: "SNAPSHOT_LIVE", startedAt: move.startedAt ?? new Date() } });
    await appendLog(move.id, "PREFLIGHT", `plan ok: ${plan.sourceNodeName} vmid ${plan.sourceVmid} → ${plan.targetNodeName} vmid ${plan.targetVmid} (${plan.addressing.kind}, ${(plan.sourceUsedBytes / 2 ** 30).toFixed(1)} GB, est. dark window ${plan.estimatedDowntimeSec}s)`);
  }

  const plan = planOf(move)!;
  const [source, target] = await Promise.all([loadMoveNode(plan.sourceNodeId), loadMoveNode(plan.targetNodeId)]);
  if (!source || !target) throw new Error("source or target node row vanished");
  const ctx: Ctx = {
    job,
    move,
    plan,
    source,
    target,
    srcConn: pveFor(source),
    tgtConn: pveFor(target),
    srcZfs: zfsHostFor(source),
    tgtZfs: zfsHostFor(target),
    dedicated: plan.addressing.kind === "DEDICATED",
    progress,
  };

  // Explicit operator rollback request (lib/vm-move/actions.ts requestVmMoveRollback).
  if ((cpOf(move) as any).rollbackRequested && rollbackAllowed(cpOf(move))) {
    const r = await rollback(ctx, "requested by operator");
    await db.vmMove.update({ where: { id: move.id }, data: { status: r.ok ? "ROLLED_BACK" : "FAILED", error: r.ok ? "rolled back on request" : `rollback errors: ${r.errors.join(" | ")}`.slice(0, 1900), finishedAt: new Date() } });
    throw new Error(r.ok ? "move rolled back on request" : `rollback incomplete: ${r.errors.join(" | ")}`);
  }

  for (;;) {
    ctx.move = (await db.vmMove.findUnique({ where: { id: move.id } }))!;
    const cp = cpOf(ctx.move);
    const phase = nextPhase(cp, { dedicated: ctx.dedicated });
    if (phase === "DONE") {
      if (ctx.move.status !== "DONE") await db.vmMove.update({ where: { id: move.id }, data: { status: "DONE", phase: "DONE", finishedAt: new Date() } });
      await progress(job.id, 100, "Move complete");
      return;
    }
    await db.vmMove.update({ where: { id: move.id }, data: { phase } });
    try {
      await runPhase(ctx, phase);
    } catch (e: any) {
      const msg = String(e?.message ?? e).slice(0, 1500);
      await appendLog(move.id, phase, `FAILED: ${msg}`);
      const inDarkWindow = !!cp.sourceStoppedAt && !cp.committedAt;
      if (inDarkWindow) {
        // Customer is down: undo now rather than wait for a retry.
        const r = await rollback(ctx, `${phase} failed: ${msg}`);
        await db.vmMove.update({
          where: { id: move.id },
          data: { status: r.ok ? "ROLLED_BACK" : "FAILED", error: `${phase}: ${msg}${r.ok ? " (rolled back; source running again)" : ` — ROLLBACK INCOMPLETE: ${r.errors.join(" | ")}`}`.slice(0, 1900), finishedAt: new Date() },
        });
        if (!r.ok) {
          await db.notification.create({ data: { userId: move.requestedById ?? (await firstAdminId()), title: `VM move ${move.id} needs attention`, body: `Rollback incomplete after ${phase} failed: ${r.errors.join(" | ")}`.slice(0, 900), href: `/admin/ops` } }).catch(() => {});
        }
        throw new Error(`${phase} failed: ${msg}${r.ok ? " — rolled back" : " — rollback incomplete"}`);
      }
      const finalAttempt = job.attempts >= MOVE_MAX_ATTEMPTS;
      if (finalAttempt && !cp.committedAt) {
        // Source still running (we never reached STOP_SOURCE) but the worker
        // will not retry again: tidy up the target side so nothing is left
        // half-received, and finalise the row.
        const r = await rollback(ctx, `${phase} failed on the last attempt: ${msg}`);
        await db.vmMove.update({
          where: { id: move.id },
          data: { status: r.ok ? "ROLLED_BACK" : "FAILED", error: `${phase}: ${msg}${r.ok ? " (target side cleaned up)" : ` — cleanup errors: ${r.errors.join(" | ")}`}`.slice(0, 1900), finishedAt: new Date() },
        });
        throw new Error(`${phase} failed: ${msg}`);
      }
      if (finalAttempt && cp.committedAt) {
        // Post-commit remainder (NAT/DNS/notices) could not finish: the DB
        // already points at the target, so say exactly what is left to do.
        await db.vmMove.update({ where: { id: move.id }, data: { status: "FAILED", error: `post-commit ${phase} failed: ${msg} — the server IS live on the target; finish NAT sync / DNS / notice by hand`.slice(0, 1900), finishedAt: new Date() } });
        throw new Error(`post-commit ${phase} failed: ${msg}`);
      }
      // Before the dark window (or after commit): keep the row RUNNING and let
      // the worker's retry resume from the last checkpoint.
      await db.vmMove.update({ where: { id: move.id }, data: { error: `${phase}: ${msg}` } });
      throw e;
    }
  }
}

