/**
 * VM_MOVE_CLEANUP — destroy the stopped source VM of a DONE move. Refuses
 * unless the DB still says the target is live AND the target hypervisor
 * agrees, and unless `keepSourceUntil` has passed (or the payload forces it).
 */
export async function vmMoveCleanupJob(job: Job, progress: Progress): Promise<void> {
  const payload = (job.payload ?? {}) as Partial<VmMoveCleanupJobPayload> & { force?: boolean };
  if (!payload.vmMoveId) throw new Error("VM_MOVE_CLEANUP job has no vmMoveId");
  const move = await db.vmMove.findUnique({ where: { id: payload.vmMoveId } });
  if (!move) throw new Error(`VmMove ${payload.vmMoveId} not found`);
  if (move.status === "CLEANED") return;
  if (move.status !== "DONE") throw new Error(`cleanup refused: move is ${move.status}, not DONE`);
  if (move.keepSourceUntil && move.keepSourceUntil.getTime() > Date.now() && !payload.force) {
    throw new Error(`cleanup refused: source is kept until ${move.keepSourceUntil.toISOString()} (pass force to override)`);
  }
  const plan = planOf(move);
  const server = await db.server.findUnique({ where: { id: move.serverId }, select: { vmid: true, nodeId: true, hostname: true } });
  if (!server || server.vmid !== move.targetVmid || server.nodeId !== move.targetNodeId) {
    throw new Error(`cleanup refused: DB says server is vmid ${server?.vmid ?? "?"} on node ${server?.nodeId ?? "?"}, not the move's target ${move.targetVmid}/${move.targetNodeId}`);
  }
  const [source, target] = await Promise.all([loadMoveNode(move.sourceNodeId), loadMoveNode(move.targetNodeId)]);
  if (!source || !target) throw new Error("source or target node row vanished");
  const tgtConn = pveFor(target);
  const srcConn = pveFor(source);
  const targetState = await vmRunning(tgtConn, move.targetVmid);
  if (targetState === null) throw new Error(`cleanup refused: target vm ${move.targetVmid} is ABSENT on ${target.name}`);
  const sourceState = await vmRunning(srcConn, move.sourceVmid);
  if (sourceState === true) throw new Error(`cleanup refused: source vm ${move.sourceVmid} on ${source.name} is RUNNING — it must be stopped (someone started it after the move?)`);

  await progress(job.id, 20, `Destroying source vm ${move.sourceVmid} on ${source.name}…`);
  const outcome = await destroyVmIdempotent(destroyHost(srcConn), move.sourceVmid);
  await appendLog(move.id, "CLEANUP", `source vm ${move.sourceVmid}: ${outcome.detail}`);
  await deleteSnippet(source, source.isPrimary ? (process.env.NXEON_SNIPPET_STORAGE ?? "backup") : source.storageHdd, `nxeon-${move.sourceVmid}.yaml`);
  if (plan?.addressing.kind === "DEDICATED" && plan.addressing.sourceService) {
    await ovhReleaseVirtualMac(plan.addressing.sourceService, plan.addressing.address, plan.addressing.sourceVirtualMac).catch((e) =>
      appendLog(move.id, "CLEANUP", `WARNING: could not release the source Virtual MAC: ${e?.message ?? e}`),
    );
  }
  await db.vmMove.update({ where: { id: move.id }, data: { status: "CLEANED", sourceCleanedAt: new Date() } });
  await db.auditLog.create({
    data: { userId: move.requestedById ?? null, action: "server.vm_move_cleanup", category: "server", target: server.hostname, detail: `destroyed source vmid ${move.sourceVmid} on ${source.name} (move ${move.id})` },
  });
  await progress(job.id, 100, "Source cleaned up");
}

 *
 * If the archive listing cannot be read we do NOT silently fall back to the raw
 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
 * and a provision that fails is recoverable while a cross-tenant disclosure is
 * not. The job retries; an operator sees why.
 */
/**
 * Atomically claim the next never-before-used vmid floor (Setting
 * `vmid_high_water`), so two concurrent PROVISIONs (WORKER_CONCURRENCY > 1)
 * never start probing from the same id, and an id is never handed out twice
 * even after its server row is deleted. One SQL statement: insert-or-bump.
 */
async function claimVmidFloor(floor: number): Promise<number> {
  const rows = await db.$queryRaw<{ value: string }[]>`
    INSERT INTO "Setting" ("key", "value") VALUES ('vmid_high_water', ${String(floor)})
    ON CONFLICT ("key") DO UPDATE
      SET "value" = GREATEST(("Setting"."value")::bigint + 1, ${floor}::bigint)::text
    RETURNING "value"`;
  const claimed = Number(rows?.[0]?.value);
  if (!Number.isInteger(claimed) || claimed <= 0) throw new Error(`vmid_high_water returned a non-integer (${rows?.[0]?.value})`);
  // Never step into the template range; jump it once and re-claim from there.
  if (isReservedVmid(claimed)) return claimVmidFloor(freshVmidFloor(claimed, [claimed]));
  return claimed;
}

async function bumpVmidHighWater(vmid: number): Promise<void> {
  await db.$executeRaw`
    UPDATE "Setting" SET "value" = GREATEST(("value")::bigint, ${vmid}::bigint)::text
    WHERE "key" = 'vmid_high_water'`;
}

async function allocateFreshVmid(conn: any, backupStorage?: string): Promise<number> {
  const nextFree = await conn.nextVmid();
  const archived = await archivedVmids(conn, backupStorage);

  // Ids already in use, so skipping forward cannot land on a live VM. Read
  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
  let taken = new Set<number>();
  try {
    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
  } catch {
    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
  }

  // `/cluster/resources` and `/nodes/.../qemu` are BOTH scoped to conn's own
  // node — each physical host is a separate, non-clustered Proxmox install
  // (see the NAT-island principle), so this node's API has zero visibility
  // into vmids live on any OTHER node, and zero visibility into a DB row
  // whose vmid survived a `qm destroy` that never cleaned up the row (found
  // live twice: node-2 offering vmid 102, then 104, each already held in the
  // DB by an unrelated server whose actual VM had been destroyed weeks
  // earlier — `Server.vmid` is unique across the WHOLE app, not per node, so
  // this is the actual source of truth to check, not any one node's API).
  const dbTaken = await db.server.findMany({ where: { vmid: { not: null } }, select: { vmid: true } });
  for (const r of dbTaken) if (r.vmid !== null) taken.add(r.vmid);
  // Templates / fixed infra ids are never candidates, whether or not this
  // node happens to have them (a golden template may exist on one node only).
  for (let id = TEMPLATE_VMID_MIN; id <= TEMPLATE_VMID_MAX; id++) taken.add(id);
  for (const id of RESERVED_VMIDS) taken.add(id);

  // Start above every id ever handed out (see freshVmidFloor), not at
  // nextid's lowest-free — which is exactly a recycled id.
  const candidate = await claimVmidFloor(
    freshVmidFloor(nextFree, dbTaken.map((r) => r.vmid).filter((v): v is number => v !== null))
  );

  const { vmid, skipped, skippedTaken, skippedArchived } = pickProvisionVmid({
    candidate,
    takenVmids: taken,
    archivedVmids: archived,
  });
  if (vmid !== candidate) await bumpVmidHighWater(vmid);
  if (skipped.length > 0) {
    // Say WHICH reason applies to which id. Reporting every skip as an archive
    // sends whoever reads this to reap archives that do not exist: on node-2
    // this line named eight ids as archive-holders when seven were live customer
    // VMs on the primary and one genuinely held an archive.
    const parts: string[] = [];
    if (skippedTaken.length) parts.push(`${skippedTaken.join(", ")} already in use (live VM or Server row)`);
    if (skippedArchived.length) parts.push(`${skippedArchived.join(", ")} still holding a previous server's backup archives`);
    console.warn(`[worker] vmid skipped for provisioning — ${parts.join("; ")}; allocated ${vmid} instead`);
  }
  return vmid;
}

