/** Every vmid the fleet knows about — live on any node, in the DB (live or archived), reserved by a move. */
export async function fleetVmidSets(targetConn: PveClient, targetBackupStorage: string): Promise<{ sets: Iterable<number>[]; unreachable: string[] }> {
  const nodes = await db.node.findMany({ select: MOVE_NODE_SELECT });
  const unreachable: string[] = [];
  const live = await Promise.all(
    nodes.map(async (n) => {
      try {
        const res: any[] = await pveFor(n).get("/cluster/resources", { type: "vm" });
        return (res ?? []).map((r) => Number(r?.vmid)).filter(Number.isInteger);
      } catch {
        unreachable.push(n.name);
        return [] as number[];
      }
    }),
  );
  const [dbVmids, archivedRows, moves] = await Promise.all([
    db.server.findMany({ where: { vmid: { not: null } }, select: { vmid: true } }),
    db.serverArchive.findMany({ where: { vmid: { not: null } }, select: { vmid: true } }),
    db.vmMove.findMany({ select: { sourceVmid: true, targetVmid: true } }),
  ]);
  let archivedOnTarget = new Set<number>();
  try {
    archivedOnTarget = await archivedVmids(targetConn, targetBackupStorage);
  } catch {
    unreachable.push(`${targetConn.node} backup storage ${targetBackupStorage}`);
  }
  const sets: Iterable<number>[] = [
    ...live,
    dbVmids.map((r) => r.vmid!),
    archivedRows.map((r) => r.vmid!),
    moves.flatMap((m) => [m.sourceVmid, m.targetVmid]),
    archivedOnTarget,
  ];
  return { sets, unreachable };
}

/** First free private IP in the target's range (not claimed — COMMIT claims via lib/ipam). */
export async function planTargetPrivateIp(targetNodeId: string): Promise<{ ip: string; gateway: string }> {
  const range = await ipamRange(targetNodeId);
  const rows = await db.server.findMany({ where: { ipAddress: { startsWith: range.subnetPrefix } }, select: { ipAddress: true } });
  const used = new Set(rows.map((r) => r.ipAddress!));
  for (let i = range.ipStart; i <= range.ipEnd; i++) {
    const ip = `${range.subnetPrefix}${i}`;
    if (!used.has(ip)) return { ip, gateway: gatewayIp(range.subnetPrefix) };
  }
  throw new Error(`IP pool exhausted on target node ${targetNodeId}`);
}

