async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
  const server = await loadServer(job);
  if (SANDBOX) {
    await db.server.update({
      where: { id: server.id },
      data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
    });
    return;
  }
  const { conn } = await nodeFor(server);
  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
  await conn.waitForTask(upid);
  await db.server.update({
    where: { id: server.id },
    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
  });
}

/**
 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
 * lib/proxmox.ts for the incident and the ladder. The bare version of this
 * function threw on an already-absent VM, which is what made a retried REINSTALL
 * destroy a customer's server permanently.
 */
async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
  const host: VmDestroyHost = {
    probe: async (id) => {
      try {
        await conn.vmStatus(id);
        return "present";
      } catch (e) {
        // Only a vmid-anchored "config does not exist" proves absence. Anything
        // else (auth, network, a locked node) is genuinely unknown and must not
        // be read as "already gone".
        return isVmAbsentError(e, id) ? "absent" : "unknown";
      }
    },
    stop: async (id) => {
      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
      await conn.waitForTask(stopUpid);
    },
    destroy: async (id) => {
      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
        "destroy-unreferenced-disks": 1,
        purge: 1,
      });
      await conn.waitForTask(delUpid, 600_000);
    },
  };
  return destroyVmIdempotent(host, vmid);
}

/**
 * Classify why a server is being deleted, from state already on the row —
 * no new column, no new customer-facing action. `suspendedNote` (ABUSE/ADMIN)
 * wins when set, since that's a stronger signal than the renewal state; short
 * of that, `autoRenew` distinguishes a customer who chose not to renew
 * (CANCELLED) from one who wanted to but nothing chargeable covered it
 * (EXPIRED). Anything else — most commonly a customer deleting a server that
 * is still paid up and not suspended — falls to DELETED.
 */
function classifyDeleteReason(server: { autoRenew: boolean; suspendedNote: string | null; expiresAt: Date | null }): string {
  if (server.suspendedNote === "ABUSE" || server.suspendedNote === "ADMIN") return "REMOVED";
  if (server.expiresAt && server.expiresAt <= new Date()) {
    return server.autoRenew ? "EXPIRED" : "CANCELLED";
  }
  return "DELETED";
}

