      gameFamily: server.gamePlan?.gameFamily ?? null,
      serviceName: server.gamePlan?.name ?? server.plan?.name ?? "—",
      nodeName: server.node?.name ?? null,
      region: server.node?.region ?? null,
      vmid: server.vmid,
      totalSpentCents: spendByServerId.get(server.id) ?? 0,
      provisionedAt: server.createdAt,
      expiresAt: server.expiresAt,
      reason: classifyDeleteReason(server),
    },
  });
}

async function remove(job: Job) {
  const server = await loadServer(job);
  const { conn, row: nodeRow } = await nodeFor(server);
  if (!SANDBOX && server.vmid) {
    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
    // so the absent case no longer needs to be caught here at all. The catch that
    // remains is narrowed to this vmid: it used to swallow any error containing
    // "does not exist", which also matches `storage 'vmdata' does not exist` and
    // `volume ... does not exist` — errors that mean the VM is very much still
    // running. On one of those the handler proceeded to delete the Server row and
    // every Volume row pinned to it, leaving a live VM with no database record:
    // invisible to billing, invisible to the panel, still holding the customer's
    // data and impossible to reach through any surface we own.
    try {
      await destroyVm(conn, server.vmid);
    } catch (e: any) {
      if (!isVmAbsentError(e, server.vmid)) throw e;
    }
    // Best-effort: remove the per-server cloud-init snippet, on whichever
    // node it actually lives — a fresh per-VM snippet for a non-primary
    // node's server was written via its node-agent (see provision() above),
    // not to this process's own local filesystem, so it must be deleted the
    // same way or it leaks as an orphaned file on that node forever.
    if (nodeRow?.isPrimary ?? true) {
      await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
    } else if (nodeRow) {
      const storage = nodeRow.storageHdd ?? SNIPPET_STORAGE;
      await agentDeleteSnippet(nodeRow, storage, `nxeon-${server.vmid}.yaml`).catch(() => {});
    }
  }
  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
  // Free this server's auto-generated Steam GSLT back into the 1000-account
  // budget (lib/steam-gslt.ts) — best-effort, same as the dedicated-IP
  // release above. Absent for every server that never got one (pre-fix, or
  // one where the customer supplied their own token instead).
  const gslteamid = (server.gameConfig as Record<string, unknown> | null)?._SRCDS_TOKEN_STEAMID;
  if (!SANDBOX && typeof gslteamid === "string") {
    await deleteGameServerAccount(gslteamid).catch((e) => console.error("[worker] Steam GSLT account release failed", e));
  }
  // Minecraft subdomain DNS (lib/game-subdomain-dns.ts): must clean up here,
  // BEFORE the row is deleted below — syncGameServerDns needs the row to still
  // exist to read `subdomain` off it.
  if (!SANDBOX && server.subdomain) await deleteMinecraftSubdomainDns(server.subdomain).catch((e) => console.error("[worker] delete game subdomain DNS failed", e));
  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
  // Volume.server is SetNull, so the rows would otherwise survive with a dead
  // diskName and keep billing forever. Remove them and notify the owner. (The
  // reinstall guard already blocks the accidental case; a full server delete is an
  // intentional teardown, so we drop the volumes with it.)
  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
  if (orphanVolumes.length > 0) {
    await db.volume.deleteMany({ where: { serverId: server.id } });
    for (const v of orphanVolumes) {
      await notify(
        v.userId,
        `Volume "${v.name}" was removed`,
        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
        "/dashboard/volumes",
      ).catch(() => {});
    }
  }
  // Snapshot this server into ServerArchive BEFORE the hard delete below — the
  // ONLY soft-delete anywhere in this schema. `db.server.delete()` truly
  // removes the row, and AuditLog's "server.delete" entry carries nothing but
  // the id, so without this snapshot a churned customer's server left no
  // trace at all — no hostname, no plan, no lifetime spend — the moment
  // this line ran. Best-effort: a failure here must never block a teardown
  // the customer (or an admin) is waiting on.
  await archiveServerBeforeDelete(server).catch((e) => console.error("[worker] archive server failed", e));
  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
  // server.delete cascade removes THIS running Job row — the success-path
  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
  await db.server.delete({ where: { id: server.id } });
  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
  // DELETE, which then dies on "Server not found" and the sync is never retried
  // (H5's aggravating factor). The failure is logged in full rather than hidden.
  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
}

