  });

  // One INTERACTIVE transaction whose FIRST act is a compare-and-swap on status: flip
  // to DELETING only if it is not already DELETING. A double-click / retry that loses
  // the race (`adv.count === 0`) does NOTHING — no second refund, no second DELETE job.
  // Only the winner issues the refund credit + ledger line + credit-note + DELETE job,
  // so refund and termination commit together and can never both run twice. (The old
  // array form flipped status unconditionally, so N concurrent calls all refunded.)
  const won = await db.$transaction(async (tx) => {
    const adv = await tx.server.updateMany({
      where: { id: server.id, status: { not: "DELETING" } },
      data: { status: "DELETING", autoRenew: false },
    });
    if (adv.count !== 1) return false; // lost the race — another call already claimed it

    if (refundCents > 0) {
      await tx.user.update({
        where: { id: server.userId },
        data: { balanceCents: { increment: refundCents } },
      });
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: refundCents,
          description: `Cancellation refund (unused term) — ${server.hostname}`,
        },
      });
      // A credit-note invoice for the refund, so the ledger line has a matching
      // billing document the customer can download. Marked REFUNDED.
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Cancellation refund — ${server.hostname}`,
          status: "REFUNDED",
          lineItems: [
            {
              description: `Prorated refund for unused term — ${server.hostname}`,
              qty: 1,
              unitCents: refundCents,
              amountCents: refundCents,
            },
          ],
        }),
      });
    }
    await tx.job.create({ data: { type: "DELETE", serverId } });
    await tx.auditLog.create({
      data: {
        userId: user.id,
        action: "server.cancel_immediate",
        detail: `${serverId} refund=${refundCents}`,
      },
    });
    return true;
  });

  if (!won) {

    return { error: "That hostname is already in use by another server — pick another." };
  }

  let server;
  try {
    server = await db.server.create({
      data: {
        name: normalizedHostname,
        hostname: normalizedHostname,
        userId: target.id,
        planId: parsed.data.planId,
        osTemplateId: parsed.data.osTemplateId,
        isFree: true,
        // Gifted outright: nothing was charged, so nothing may prorate out. (A free
        // server has a null `expiresAt` and prorates to zero anyway, but this row can
        // later be given an expiry by adminSetServerFree/adminExtendServer, and the
        // rate basis must already be honest when that happens.)
        termPromoPercent: 100,
      },
    });
  } catch (e) {
    if (isHostnameConflict(e)) return { error: "That hostname was just taken by another server — pick another." };
    throw e;
  }
  await db.job.create({ data: { type: "PROVISION", serverId: server.id } });
  await audit(admin.id, "admin.grant_free_vps", `user=${target.email} server=${server.id}`);
  redirect(`/admin/servers`);
}

export async function adminSuspendServer(serverId: string, suspend: boolean) {
  const admin = await requireAdmin();
  // Record WHY. An admin suspension is NOT an unpaid one: the renewal sweep skips
  // suspended servers, so a paid-up customer suspended here is never charged and
  // never warned — and before `suspendReason` existed, `terminateOverdue` then
  // deleted their VM and all its data once the untouched term lapsed. Tagging it
  // ADMIN keeps the terminator away from it and stops "Renew now" silently
  // reversing an administrative decision.
  await db.server.update({
    where: { id: serverId },
    data: suspend
      ? { suspendReason: "ADMIN", suspendedNote: "suspended by support — contact us to restore access" }
      : { suspendReason: null, suspendedNote: null },
  });
  await db.job.create({ data: { type: suspend ? "SUSPEND" : "UNSUSPEND", serverId } });
  await audit(admin.id, suspend ? "admin.suspend_server" : "admin.unsuspend_server", serverId);
  revalidatePath("/admin/servers");
}

