/** DELETE /v1/zfs/snapshot {dataset, snap} — only this engine's own snapshots. */
async function handleZfsDeleteSnapshot(_req, res, rawBody) {
  const p = parseJson(rawBody);
  if (!p || !parseVmDataset(p.dataset) || !isStr(p.snap, MOVE_SNAPSHOT_RE)) return sendJson(res, 400, { error: "invalid dataset/snapshot" });
  try {
    await zfs(["destroy", `${p.dataset}@${p.snap}`]);
  } catch (e) {
    if (!/does not exist/.test(e.message)) throw e;
  }
  sendJson(res, 200, { ok: true });
}

/** DELETE /v1/zfs/dataset {dataset} — rollback of a half-received disk. Refused
 *  outright when a VM config for that vmid exists on this node: a disk that
 *  belongs to a configured VM is destroyed through Proxmox (qm destroy), by the
 *  worker, via the API — never by this agent. */
async function handleZfsDestroyDataset(_req, res, rawBody) {
  const p = parseJson(rawBody);
  const parsed = p && parseVmDataset(p.dataset);
  if (!parsed) return sendJson(res, 400, { error: "invalid dataset" });
  if (vmConfigExists(parsed.vmid)) return sendJson(res, 409, { error: `vm ${parsed.vmid} has a config on this node — destroy it through Proxmox, not here` });
  try {
    await zfs(["destroy", "-r", p.dataset]);
  } catch (e) {
    if (!/does not exist/.test(e.message)) throw e;
  }
  sendJson(res, 200, { ok: true });
}

/**
 * POST /v1/zfs/recv?dataset=… — body is a zstd-compressed `zfs send` stream.
 * Decompressed and received with `-F` (so an incremental lands on the full
 * pass's snapshot) and `-u` (never try to mount anything). Refuses a dataset
 * whose vmid already has a VM config here (that would be someone's live
 * disk), and refuses to create a dataset whose pool path doesn't exist.
 */
async function handleZfsRecv(req, res, dataset) {
  const parsed = parseVmDataset(dataset);
  if (!parsed) return sendJson(res, 400, { error: "invalid dataset" });
  if (vmConfigExists(parsed.vmid)) return sendJson(res, 409, { error: `vm ${parsed.vmid} already has a config on this node` });
  try {
    await zfs(["list", "-H", "-o", "name", parsed.pool]);
  } catch {
    return sendJson(res, 400, { error: `pool ${parsed.pool} does not exist on this node` });
  }
  const zstd = spawn("zstd", ["-d", "-q", "-T0"], { stdio: ["pipe", "pipe", "pipe"] });
  const recv = spawn("zfs", ["receive", "-F", "-u", dataset], { stdio: ["pipe", "pipe", "pipe"] });
  let recvErr = "";
  recv.stderr.on("data", (d) => (recvErr += d.toString().slice(0, 1000)));
  let zstdErr = "";
  zstd.stderr.on("data", (d) => (zstdErr += d.toString().slice(0, 1000)));
  const recvDone = new Promise((resolve, reject) => {
    recv.on("error", reject);
    recv.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`zfs receive exited ${code}: ${recvErr.trim()}`))));
  });
  try {
    zstd.stdout.pipe(recv.stdin);
    await pipeline(req, zstd.stdin);
    await recvDone;
  } catch (e) {
    try { zstd.kill("SIGKILL"); } catch { /* already gone */ }
    try { recv.kill("SIGKILL"); } catch { /* already gone */ }
    throw new Error(`${e.message}${zstdErr ? ` (zstd: ${zstdErr.trim()})` : ""}`);
  }
  sendJson(res, 200, { ok: true });
}

/**
 * GET /v1/zfs/send?dataset=…&snap=…[&from=…] — streams a zstd-compressed
 * `zfs send` of `dataset@snap` (incremental from `@from` when given). Used
 * when THIS node is the source of a move; the primary pipes it straight into
 * the target's recv endpoint.
 */
async function handleZfsSend(_req, res, dataset, snap, from) {
  if (!parseVmDataset(dataset)) return sendJson(res, 400, { error: "invalid dataset" });
  if (!isStr(snap, MOVE_SNAPSHOT_RE) || (from !== null && !isStr(from, MOVE_SNAPSHOT_RE))) return sendJson(res, 400, { error: "invalid snapshot" });
  const args = ["send", "-L", "-e"];
  if (from) args.push("-i", `${dataset}@${from}`);
  args.push(`${dataset}@${snap}`);
  const send = spawn("zfs", args, { stdio: ["ignore", "pipe", "pipe"] });
  const zstd = spawn("zstd", ["-3", "-q", "-T1"], { stdio: ["pipe", "pipe", "pipe"] });
  let sendErr = "";
  send.stderr.on("data", (d) => (sendErr += d.toString().slice(0, 1000)));
  send.on("close", (code) => {
    if (code !== 0) {
      console.error(`[node-agent] zfs send ${dataset}@${snap} exited ${code}: ${sendErr.trim()}`);
      // Truncate the response so the receiver's zstd/zfs receive fails loudly
      // instead of accepting a short stream as complete.
      try { zstd.kill("SIGKILL"); } catch { /* gone */ }
      res.destroy();
    }
  });
  res.writeHead(200, { "Content-Type": "application/octet-stream" });
  send.stdout.pipe(zstd.stdin);
  zstd.stdout.pipe(res);
  res.on("close", () => {
    try { send.kill("SIGKILL"); } catch { /* gone */ }
    try { zstd.kill("SIGKILL"); } catch { /* gone */ }
  });
}

