// ---------------------------------------------------------------------------
// op: drift_scan + cleanups
// ---------------------------------------------------------------------------

async function opDriftScan(job: Job): Promise<void> {
  const nodes = await db.node.findMany({ orderBy: { createdAt: "asc" } });
  const vmsByNode: Record<string, PveVm[] | null> = {};
  let i = 0;
  for (const n of nodes) {
    await step(job, `Reading VMs on ${n.name}…`, Math.round((i++ / Math.max(nodes.length, 1)) * 70));
    if (SANDBOX) {
      const rows = await db.server.findMany({ where: { OR: [{ nodeId: n.id }, ...(n.isPrimary ? [{ nodeId: null }] : [])], vmid: { not: null } }, select: { vmid: true, hostname: true, status: true } });
      vmsByNode[n.id] = [
        ...rows.map((r) => ({ vmid: r.vmid!, name: r.hostname, status: r.status === "RUNNING" ? "running" : "stopped", tags: "nxeon" })),
        { vmid: 9000, template: 1 },
        { vmid: 9001, template: 1 },
      ];
      continue;
    }
    vmsByNode[n.id] = await soft(async () => {
      const list = await clientFor(n).get(`/nodes/${n.pveNode}/qemu`);
      return (Array.isArray(list) ? list : []).map((v: any) => ({ vmid: Number(v.vmid), name: v.name, status: v.status, tags: v.tags, template: v.template }));
    }, 20_000);
  }
  await step(job, "Comparing with the database…", 80);
  const [servers, ips, archives, templates, inflightRows] = await Promise.all([
    db.server.findMany({ select: { id: true, hostname: true, vmid: true, nodeId: true, status: true, ipAddress: true, updatedAt: true } }),
    db.dedicatedIp.findMany({ select: { id: true, address: true, status: true, serverId: true, nodeId: true, purpose: true } }),
    db.serverArchive.findMany({ where: { vmid: { not: null } }, select: { vmid: true, hostname: true, deletedAt: true }, orderBy: { deletedAt: "desc" }, take: 2000 }),
    db.osTemplate.findMany({ where: { active: true }, select: { vmid: true, baseVmid: true } }),
    db.job.findMany({ where: { status: { in: ["QUEUED", "RUNNING"] }, serverId: { not: null } }, select: { serverId: true } }),
  ]);
  const busy = new Set(inflightRows.map((r) => r.serverId!));
  const archivedByVmid: Record<number, { hostname: string; deletedAt: Date }> = {};
  for (const a of archives) if (a.vmid != null && !archivedByVmid[a.vmid]) archivedByVmid[a.vmid] = { hostname: a.hostname, deletedAt: a.deletedAt };
  const templateVmids = [...new Set(templates.flatMap((t) => [t.vmid, t.baseVmid].filter((v): v is number => typeof v === "number" && v >= 9000 && v <= 9999)))].sort((a, b) => a - b);
  const findings = detectDrift({
    nodes: nodes.map((n) => ({ id: n.id, name: n.name, isPrimary: n.isPrimary, enabled: n.enabled, acceptsProvisions: n.acceptsProvisions })),
    vmsByNode,
    servers: servers.map((s) => ({ ...s, hasInflightJob: busy.has(s.id) })),
    dedicatedIps: ips,
    archivedByVmid,
    templateVmids,
    prodTag: process.env.NXEON_TAG ?? "nxeon",
  });
  await finish(job, {
    ok: true,
    findings,
    scannedNodes: nodes.map((n) => ({ id: n.id, name: n.name, vms: vmsByNode[n.id]?.length ?? null })),
    templateVmids,
  });
}

async function opOrphanVmDestroy(job: Job, p: OrphanVmDestroyPayload): Promise<void> {
  const node = await db.node.findUnique({ where: { id: p.nodeId } });
  if (!node) return failTerminal(job, "Node not found.");
  if (!Number.isInteger(p.vmid) || p.vmid < 100 || (p.vmid >= 9000 && p.vmid <= 9999)) return failTerminal(job, "Refusing: templates (9000-9999) and system vmids are never destroyed.");
  const owner = await db.server.findFirst({ where: { vmid: p.vmid }, select: { hostname: true } });
  if (owner) return failTerminal(job, `Refusing: vmid ${p.vmid} belongs to server ${owner.hostname} — delete it through its DELETE job.`);
  if (SANDBOX) {
    await audit(p.requestedBy, "adminops.orphan_vm_destroy", `(sandbox) ${node.name} vmid ${p.vmid}`);
    return finish(job, { ok: true, detail: `[sandbox] VM ${p.vmid} on ${node.name} would be destroyed.` });
  }
  const conn = clientFor(node);
  // Re-verify at run time: still platform-tagged, still stopped, still unowned.
  const cfg = await soft(() => conn.get(`/nodes/${conn.node}/qemu/${p.vmid}/config`), 10_000);
  const st = await soft(() => conn.vmStatus(p.vmid), 10_000);
  if (!cfg || !st) return failTerminal(job, `VM ${p.vmid} could not be read on ${node.name} (already gone?).`);
  const tags = String(cfg.tags ?? "").split(/[;,\s]+/).map((t: string) => t.toLowerCase());
  const prodTag = (process.env.NXEON_TAG ?? "nxeon").toLowerCase();
  if (!tags.includes(prodTag)) return failTerminal(job, `Refusing: VM ${p.vmid} is not tagged "${prodTag}" — it is not a platform VM.`);
  if (cfg.template) return failTerminal(job, "Refusing: that VM is a template.");
  if (st.status !== "stopped") return failTerminal(job, `Refusing: VM ${p.vmid} is ${st.status}. Stop it deliberately first.`);
  const host: VmDestroyHost = {
    probe: async (id) => {
      try {
        await conn.vmStatus(id);
        return "present";
      } catch (e) {
        return isVmAbsentError(e, id) ? "absent" : "unknown";
      }
    },
    stop: async () => {
      /* verified stopped above */
    },
    destroy: async (id) => {
      const upid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, { "destroy-unreferenced-disks": 1, purge: 1 });
      await conn.waitForTask(upid, 600_000);
    },
  };
  await step(job, `Destroying VM ${p.vmid} on ${node.name}…`, 50);
  const outcome = await destroyVmIdempotent(host, p.vmid);
  await audit(p.requestedBy, "adminops.orphan_vm_destroy", `${node.name} vmid ${p.vmid}: ${outcome.detail} reason="${p.reason ?? ""}"`);
  await finish(job, { ok: true, detail: outcome.detail });
}

async function opOrphanIpRelease(job: Job, p: OrphanIpReleasePayload): Promise<void> {
  const ip = await db.dedicatedIp.findUnique({ where: { id: p.ipId }, include: { node: true } });
  if (!ip) return failTerminal(job, "IP row not found.");
  const holder = await db.server.findFirst({ where: { ipAddress: ip.address }, select: { hostname: true } });
  if (holder) return failTerminal(job, `Refusing: ${holder.hostname} still holds ${ip.address}.`);
  if (ip.serverId) {
    const owner = await db.server.findUnique({ where: { id: ip.serverId }, select: { hostname: true } });
    if (owner) return failTerminal(job, `Refusing: ${owner.hostname} still owns this row — use IP release on that server.`);
  }
  if (!SANDBOX) {
    // A live whole-IP DNAT on its node means infrastructure is using it.
    const live = ip.node.isPrimary
      ? await soft(async () => {
          const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"], { timeout: 10_000 });
          return stdout.split("\n").some((l) => l.includes(`-d ${ip.address}/32`) && l.includes("-j DNAT"));
        })
      : await soft(() => agentHasLiveDnatRule(ip.node, ip.address));
    if (live) return failTerminal(job, `Refusing: ${ip.address} is the target of a live DNAT rule on ${ip.node.name} (infrastructure is using it). Mark it INTERNAL instead.`);
  }
  // Same provider cleanup releaseDedicatedIp does (it needs a live serverId,
  // which an orphan by definition no longer has): drop an OVH virtual MAC so it
  // stops billing; a Hetzner MAC is per-IP and deliberately kept for reuse.
  let note: string | null = null;
  if (!SANDBOX && ip.node.provider === "OVH" && ip.virtualMac && ip.node.providerServerId) {
    if (ovhConfigured()) {
      const SERVER = ip.node.providerServerId;
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
    } else {
      note = "OVH API not configured — the recorded virtual MAC was not removed; check the provider panel.";
    }
  }
  await db.dedicatedIp.update({ where: { id: ip.id }, data: { status: "FREE", serverId: null, virtualMac: ip.node.provider === "HETZNER" ? ip.virtualMac : null } });
  await audit(p.requestedBy, "adminops.orphan_ip_release", `${ip.address} on ${ip.node.name} reason="${p.reason ?? ""}"`);
  await finish(job, { ok: true, address: ip.address, note });
}

