async function opBulkPower(job: Job, p: BulkPowerPayload): Promise<void> {
  let children: ChildState[] = p.children ?? [];
  if (!children.length) {
    const servers = await db.server.findMany({
      where: { id: { in: p.serverIds } },
      select: { id: true, hostname: true, status: true, gamePlanId: true, isFree: true, user: { select: { role: true, excludeFromRevenue: true } } },
    });
    const busy = new Set((await db.job.findMany({ where: { serverId: { in: p.serverIds }, status: { in: ["QUEUED", "RUNNING"] } }, select: { serverId: true } })).map((r) => r.serverId!));
    children = p.serverIds.map((id) => {
      const s = servers.find((x) => x.id === id);
      if (!s) return { serverId: id, jobId: null, skipped: "not found" };
      const why = bulkIneligible(p.action, {
        id: s.id,
        hostname: s.hostname,
        status: s.status,
        isGame: !!s.gamePlanId,
        hasInflightJob: busy.has(s.id),
        ownerIsStaff: s.user.role !== "CUSTOMER",
        ownerExcludedFromRevenue: s.user.excludeFromRevenue,
        isFree: s.isFree,
      });
      return { serverId: id, jobId: null, skipped: why ?? undefined };
    });
    await patchPayload(job, { children });
  }
  const spec = childJobFor(p.action);
  const deadline = Date.now() + 6 * 3600_000;
  for (;;) {
    // Refresh child statuses.
    const ids = children.filter((c) => c.jobId).map((c) => c.jobId!);
    const rows = ids.length ? await db.job.findMany({ where: { id: { in: ids } }, select: { id: true, status: true } }) : [];
    for (const c of children) if (c.jobId) c.status = rows.find((r) => r.id === c.jobId)?.status ?? "DONE";
    if (bulkDone(children)) break;
    for (const serverId of nextWave(children, p.concurrency)) {
      const c = children.find((x) => x.serverId === serverId)!;
      const created = await withServerJobLock(serverId, async (tx) => {
        const pending = await tx.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
        if (pending > 0) return null;
        if (spec.type === "DELETE") await tx.server.update({ where: { id: serverId }, data: { status: "DELETING" } });
        return tx.job.create({ data: { type: spec.type, serverId, ...(spec.payload ? { payload: spec.payload as Prisma.InputJsonValue } : {}) }, select: { id: true } });
      });
      if (created) {
        c.jobId = created.id;
        c.status = "QUEUED";
      } else {
        c.skipped = "another job appeared before its turn";
      }
    }
    const done = children.filter((c) => c.skipped || c.status === "DONE" || c.status === "FAILED").length;
    await patchPayload(job, { children });
    await step(job, `${done}/${children.length} finished`, Math.round((done / Math.max(children.length, 1)) * 100));
    if (Date.now() > deadline) return failTerminal(job, "Bulk run exceeded 6h — remaining children left as they are.", { ok: false, children });
    await new Promise((r) => setTimeout(r, 4000));
  }
  const summary = {
    ok: true,
    action: p.action,
    done: children.filter((c) => c.status === "DONE").length,
    failed: children.filter((c) => c.status === "FAILED").length,
    skipped: children.filter((c) => c.skipped).length,
    children,
  };
  await audit(p.requestedBy, "adminops.bulk_power", `${p.action} x${children.length}: done=${summary.done} failed=${summary.failed} skipped=${summary.skipped} reason="${p.reason ?? ""}"`);
  await finish(job, summary);
}

