export async function adminOps(job: Job): Promise<void> {
  const p = (job.payload ?? {}) as unknown as AdminOpPayload;
  switch (p.op) {
    case "diagnose":
      return opDiagnose(job, p);
    case "guest_cmd":
      return opGuestCmd(job, p);
    case "ip_reassign":
      return opIpReassign(job, p);
    case "ip_release":
      return opIpRelease(job, p);
    case "ip_assign":
      return opIpAssign(job, p);
    case "drift_scan":
      return opDriftScan(job);
    case "orphan_vm_destroy":
      return opOrphanVmDestroy(job, p);
    case "orphan_ip_release":
      return opOrphanIpRelease(job, p);
    case "bulk_power":
      return opBulkPower(job, p);
    case "hold":
      // Re-queued by a worker restart: the op it was guarding is gone — release.
      return finish(job, { ok: true, released: true });
    default:
      return failTerminal(job, `Unknown admin op: ${String((p as { op?: unknown }).op).slice(0, 40)}`);
  }
}
/**
 * DB-vs-Proxmox drift / orphan detector — PURE. worker/admin-ops.ts collects
 * every node's VM list + the relevant DB rows and hands them here; this
 * decides what is wrong and which findings are SAFE to clean up in one click.
 *
 * Safety rules baked in (each from a real near-miss in this fleet):
 *  - A VM is only an "orphan" if it carries the PRODUCTION platform tag
 *    (provision() tags every VM `${NXEON_TAG};user-xxxx`) AND no Server row
 *    owns that vmid. Staging shares the primary node with its own tag and
 *    must never be flagged; untagged VMs (mail, Kodely, hosting node, cold-
 *    email relay…) are internal infrastructure — reported, never offered for
 *    destruction.
 *  - Templates (vmid 9000-9999 or `template: 1`) are never orphans.
 *  - One-click destroy is offered only for a STOPPED orphan. A running orphan
 *    may be something real that lost its row; stop it deliberately first.
 *  - A dedicated IP is only "orphaned" when its row claims a server that no
 *    longer exists (or claims none while ASSIGNED). It is never released
 *    while a live Server row still holds that address.
 */

export type DriftSeverity = "high" | "medium" | "low" | "info";

export type DriftFixKey = "reconcile_status" | "orphan_vm_destroy" | "orphan_ip_release" | "sync_forwards" | "diagnose";

export type DriftFinding = {
  kind:
    | "orphan_vm"
    | "unmanaged_vm"
    | "missing_vm"
    | "wrong_node"
    | "status_mismatch"
    | "stranded_transitional"
    | "duplicate_vmid"
    | "ip_orphan"
    | "ip_mismatch"
    | "ip_conflict"
    | "template_missing"
    | "node_unreachable";
  severity: DriftSeverity;
  title: string;
  detail: string;
  nodeId?: string;
  nodeName?: string;
  vmid?: number;
  serverId?: string;
  hostname?: string;
  ipId?: string;
  fix?: DriftFixKey;
};

export type PveVm = { vmid: number; name?: string; status?: string; tags?: string; template?: number | boolean };

export type DriftInput = {
  nodes: { id: string; name: string; isPrimary: boolean; enabled: boolean; acceptsProvisions: boolean }[];
  /** nodeId -> its VM list, or null when that node's API could not be read. */
  vmsByNode: Record<string, PveVm[] | null>;
  servers: {
    id: string;
    hostname: string;
    vmid: number | null;
    nodeId: string | null;
    status: string;
    ipAddress: string | null;
    updatedAt: Date;
    hasInflightJob: boolean;
  }[];
  dedicatedIps: { id: string; address: string; status: string; serverId: string | null; nodeId: string; purpose: string }[];
  /** Archived (deleted) servers by vmid, for labelling leftovers. */
  archivedByVmid: Record<number, { hostname: string; deletedAt: Date }>;
  /** Template vmids every provision-accepting node must carry. */
  templateVmids: number[];
  prodTag: string;
  now?: Date;
};

export function isTemplateVm(v: PveVm): boolean {
  return v.template === 1 || v.template === true || (v.vmid >= 9000 && v.vmid <= 9999);
}

export function vmTags(v: PveVm): string[] {
  return String(v.tags ?? "")
    .split(/[;,\s]+/)
    .map((t) => t.trim().toLowerCase())
    .filter(Boolean);
}

const TRANSITIONAL = new Set(["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"]);
const STRANDED_MIN = 60;

export function detectDrift(input: DriftInput): DriftFinding[] {
  const now = input.now ?? new Date();
  const out: DriftFinding[] = [];
  const prodTag = input.prodTag.toLowerCase();
  const primary = input.nodes.find((n) => n.isPrimary);
  const nodeName = (id: string | null | undefined) => input.nodes.find((n) => n.id === id)?.name ?? "?";
  const nodeOf = (s: { nodeId: string | null }) => s.nodeId ?? primary?.id ?? null;

  const serverByVmid = new Map<number, DriftInput["servers"][number]>();
  for (const s of input.servers) if (s.vmid != null) serverByVmid.set(s.vmid, s);

  // vmid -> nodes it appears on (real VMs only)
  const seenOn = new Map<number, string[]>();
  for (const n of input.nodes) {
    const vms = input.vmsByNode[n.id];
    if (vms == null) {
      out.push({
        kind: "node_unreachable",
        severity: "high",
        title: `Could not read VMs on ${n.name}`,
        detail: "The node's Proxmox API did not answer — drift on this node is unknown, nothing below covers it.",
        nodeId: n.id,
        nodeName: n.name,
      });
      continue;
    }
    for (const v of vms) {
      if (isTemplateVm(v)) continue;
      seenOn.set(v.vmid, [...(seenOn.get(v.vmid) ?? []), n.id]);
      const owner = serverByVmid.get(v.vmid);
      if (owner) {
        const ownerNode = nodeOf(owner);
        if (ownerNode !== n.id) continue; // handled by wrong_node below
        // status mismatch (only for settled DB states)
        const pve = String(v.status ?? "");
        if (!owner.hasInflightJob && !TRANSITIONAL.has(owner.status)) {
          if ((owner.status === "RUNNING" && pve === "stopped") || ((owner.status === "STOPPED" || owner.status === "ERROR") && pve === "running")) {
            out.push({
              kind: "status_mismatch",
              severity: owner.status === "RUNNING" ? "high" : "medium",
              title: `${owner.hostname}: DB says ${owner.status}, Proxmox says ${pve}`,
              detail: "The dashboard and power controls follow the DB row; reconcile reads the hypervisor and corrects it.",
              nodeId: n.id,
              nodeName: n.name,
              vmid: v.vmid,
              serverId: owner.id,
              hostname: owner.hostname,
              fix: "reconcile_status",
            });
          }
        }
        continue;
      }
      const tags = vmTags(v);
      const archived = input.archivedByVmid[v.vmid];
      if (tags.includes(prodTag)) {
        const stopped = v.status === "stopped";
        out.push({
          kind: "orphan_vm",
          severity: stopped ? "medium" : "high",
          title: `Orphan VM ${v.vmid}${v.name ? ` (${v.name})` : ""} on ${n.name}`,
          detail:
            (archived
              ? `Leftover of deleted server ${archived.hostname} (deleted ${archived.deletedAt.toISOString().slice(0, 10)}). `
              : "Platform-tagged VM with no Server row. ") +
            (stopped
              ? "It is stopped and safe to destroy (its vmid is never reused)."
              : `It is ${v.status ?? "in an unknown state"} — stop it deliberately before destroying; it may be something real that lost its row.`),
          nodeId: n.id,
          nodeName: n.name,
          vmid: v.vmid,
          fix: stopped ? "orphan_vm_destroy" : undefined,
        });
      } else if (!tags.some((t) => t.startsWith("nxeon"))) {
        out.push({
          kind: "unmanaged_vm",
          severity: "info",
          title: `Unmanaged VM ${v.vmid}${v.name ? ` (${v.name})` : ""} on ${n.name}`,
          detail: "No platform tag and no Server row — internal infrastructure or a hand-made VM. Never cleaned up automatically.",
          nodeId: n.id,
          nodeName: n.name,
          vmid: v.vmid,
        });
      }
    }
  }

  for (const [vmid, nodes] of seenOn) {
    if (nodes.length > 1) {
      out.push({
        kind: "duplicate_vmid",
        severity: "medium",
        title: `vmid ${vmid} exists on ${nodes.length} nodes`,
        detail: `Present on ${nodes.map(nodeName).join(", ")}. The nodes aren't clustered so Proxmox allows it, but every vmid-keyed lookup becomes ambiguous.`,
        vmid,
      });
    }
  }

  // Servers whose VM is not where the DB says.
  for (const s of input.servers) {
    if (s.vmid == null) {
      if (TRANSITIONAL.has(s.status) && !s.hasInflightJob && (now.getTime() - s.updatedAt.getTime()) / 60_000 >= STRANDED_MIN) {
        out.push({
          kind: "stranded_transitional",
          severity: "high",
          title: `${s.hostname} stuck in ${s.status} with no job`,
          detail: `No VM, no in-flight job, untouched for ${Math.round((now.getTime() - s.updatedAt.getTime()) / 60_000)} min.`,
          serverId: s.id,
          hostname: s.hostname,
          fix: "diagnose",
        });
      }
      continue;
    }
    const nid = nodeOf(s);
    if (!nid) continue;
    const vms = input.vmsByNode[nid];
    if (vms == null) continue; // node unreachable, already reported
    const here = vms.some((v) => v.vmid === s.vmid && !isTemplateVm(v));
    if (!here && s.status !== "DELETING") {
      const elsewhere = (seenOn.get(s.vmid) ?? []).filter((x) => x !== nid);
      out.push(
        elsewhere.length
          ? {
              kind: "wrong_node",
              severity: "high",
              title: `${s.hostname}: VM ${s.vmid} is on ${elsewhere.map(nodeName).join(", ")}, DB says ${nodeName(nid)}`,
              detail: "Every action for this server is sent to the wrong node. Fix the Server.nodeId record (or finish the move) before anything else.",
              serverId: s.id,
              hostname: s.hostname,
              vmid: s.vmid,
              nodeId: nid,
              nodeName: nodeName(nid),
            }
          : {
              kind: "missing_vm",
              severity: "high",
              title: `${s.hostname}: VM ${s.vmid} not found on any node`,
              detail: `Server row is ${s.status} but no node has this vmid. The VM was destroyed outside the platform, or the row was never cleaned up.`,
              serverId: s.id,
              hostname: s.hostname,
              vmid: s.vmid,
              nodeId: nid,
              nodeName: nodeName(nid),
              fix: "diagnose",
            },
      );
      continue;
    }
    if (TRANSITIONAL.has(s.status) && !s.hasInflightJob && (now.getTime() - s.updatedAt.getTime()) / 60_000 >= STRANDED_MIN) {
      out.push({
        kind: "stranded_transitional",
        severity: "high",
        title: `${s.hostname} stuck in ${s.status} with no job`,
        detail: "The VM exists but no job is working on it. Reconcile reads the real power state and corrects the row.",
        serverId: s.id,
        hostname: s.hostname,
        vmid: s.vmid,
        nodeId: nid,
        nodeName: nodeName(nid),
        fix: "reconcile_status",
      });
    }
  }

  // Dedicated IP pool consistency.
  const serverById = new Map(input.servers.map((s) => [s.id, s]));
  const serverByIp = new Map<string, DriftInput["servers"][number]>();
  for (const s of input.servers) if (s.ipAddress) serverByIp.set(s.ipAddress, s);
  for (const ip of input.dedicatedIps) {
    const holder = serverByIp.get(ip.address);
    if (ip.serverId) {
      const owner = serverById.get(ip.serverId);
      if (!owner) {
        out.push({
          kind: "ip_orphan",
          severity: "medium",
          title: `${ip.address} is assigned to a server that no longer exists`,
          detail: holder
            ? `…but live server ${holder.hostname} still holds this address — NOT safe to release; diagnose ${holder.hostname}.`
            : "Nothing holds the address. Releasing returns it to the free pool (and removes its OVH virtual MAC).",
          ipId: ip.id,
          nodeId: ip.nodeId,
          nodeName: nodeName(ip.nodeId),
          fix: holder ? undefined : "orphan_ip_release",
        });
        continue;
      }
      if (owner.ipAddress !== ip.address) {
        out.push({
          kind: "ip_mismatch",
          severity: "high",
          title: `${owner.hostname} owns ${ip.address} in the pool but its row says ${owner.ipAddress ?? "nothing"}`,
          detail: "Forwards, DNS and the dashboard use Server.ipAddress. Diagnose the server to see what the VM really has.",
          ipId: ip.id,
          serverId: owner.id,
          hostname: owner.hostname,
          fix: "diagnose",
        });
      }
      if (owner.nodeId && owner.nodeId !== ip.nodeId) {
        out.push({
          kind: "ip_mismatch",
          severity: "high",
          title: `${owner.hostname} is on ${nodeName(owner.nodeId)} but holds ${nodeName(ip.nodeId)}'s IP ${ip.address}`,
          detail: "A failover IP routes only to the node that owns it — this address cannot reach the VM.",
          ipId: ip.id,
          serverId: owner.id,
          hostname: owner.hostname,
        });
      }
    } else {
      if (ip.status === "ASSIGNED" || ip.status === "PENDING" || ip.status === "RELEASING") {
        out.push({
          kind: "ip_orphan",
          severity: "medium",
          title: `${ip.address} is ${ip.status} with no server`,
          detail: holder
            ? `…but ${holder.hostname} still holds it in its row — NOT safe to release.`
            : "Half-finished allocation/release. Releasing marks it FREE again.",
          ipId: ip.id,
          nodeId: ip.nodeId,
          nodeName: nodeName(ip.nodeId),
          fix: holder ? undefined : "orphan_ip_release",
        });
      }
      if (holder && ip.purpose === "CUSTOMER") {
        out.push({
          kind: "ip_conflict",
          severity: "high",
          title: `${ip.address} is ${ip.status} in the pool but ${holder.hostname} is using it`,
          detail: "The next allocation could hand this live address to a second server. Diagnose the holder and either link or re-IP it.",
          ipId: ip.id,
          serverId: holder.id,
          hostname: holder.hostname,
          fix: "diagnose",
        });
      }
    }
  }

  // Templates every provisioning node must have.
  for (const n of input.nodes) {
    if (!n.enabled || !n.acceptsProvisions) continue;
    const vms = input.vmsByNode[n.id];
    if (vms == null) continue;
    const have = new Set(vms.filter(isTemplateVm).map((v) => v.vmid));
    const missing = input.templateVmids.filter((t) => !have.has(t));
    if (missing.length) {
      out.push({
        kind: "template_missing",
        severity: "medium",
        title: `${n.name} is missing ${missing.length} template(s)`,
        detail: `vmid ${missing.slice(0, 12).join(", ")}${missing.length > 12 ? "…" : ""} — orders for those images fail on this node. Re-run the template sync for this node.`,
        nodeId: n.id,
        nodeName: n.name,
      });
    }
  }

  const rank: Record<DriftSeverity, number> = { high: 0, medium: 1, low: 2, info: 3 };
  return out.sort((a, b) => rank[a.severity] - rank[b.severity]);
}

