export async function startDriftScan(): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  const existing = await db.job.findFirst({ where: { type: "ADMIN_OPS", status: { in: ["QUEUED", "RUNNING"] }, payload: { path: ["op"], equals: "drift_scan" } }, select: { id: true } });
  if (existing) return { ok: true, jobId: existing.id };
  const jobId = await enqueue({ op: "drift_scan", requestedBy: admin.id });
  await recordAudit(admin.id, "adminops.drift_scan.request", "fleet");
  return { ok: true, jobId };
}

export async function latestDriftScan(): Promise<OpJobView | null> {
  await gate();
  const j = await db.job.findFirst({ where: { type: "ADMIN_OPS", payload: { path: ["op"], equals: "drift_scan" } }, orderBy: { createdAt: "desc" }, select: { id: true } });
  return j ? getOpJob(j.id) : null;
}

export async function startOrphanVmDestroy(nodeId: string, vmid: number, reason: string, confirm: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  if (badId(nodeId) || !Number.isInteger(vmid) || vmid < 100) return { ok: false, error: "Invalid target." };
  if (vmid >= 9000 && vmid <= 9999) return { ok: false, error: "Templates (9000-9999) are never destroyed." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  if (confirm.trim() !== String(vmid)) return { ok: false, error: `Type the vmid (${vmid}) to confirm.` };
  const owner = await db.server.findFirst({ where: { vmid }, select: { hostname: true } });
  if (owner) return { ok: false, error: `vmid ${vmid} belongs to ${owner.hostname} — never destroy a VM with a Server row; use its DELETE job.` };
  const jobId = await enqueue({ op: "orphan_vm_destroy", requestedBy: admin.id, reason: why, nodeId, vmid, lockKey: `vm:${nodeId}:${vmid}` });
  await recordAudit(admin.id, "adminops.orphan_vm_destroy.request", `${nodeId} vmid ${vmid} reason="${why}"`);
  return { ok: true, jobId };
}

export async function startOrphanIpRelease(ipId: string, reason: string): Promise<Ok<{ jobId: string }>> {
  const admin = await gate();
  if (badId(ipId)) return { ok: false, error: "Invalid IP." };
  const why = cleanReason(reason);
  if (!why) return { ok: false, error: "Give a reason (4-300 characters)." };
  const ip = await db.dedicatedIp.findUnique({ where: { id: ipId }, select: { address: true } });
  if (!ip) return { ok: false, error: "IP not found." };
  const jobId = await enqueue({ op: "orphan_ip_release", requestedBy: admin.id, reason: why, ipId, lockKey: `ip:${ipId}` });
  await recordAudit(admin.id, "adminops.orphan_ip_release.request", `${ip.address} reason="${why}"`);
  return { ok: true, jobId };
}

