  for (const s of servers) {
    const nodeId = (s as { nodeId?: string | null }).nodeId ?? primary?.id;
    if (!nodeId) continue; // no node row at all yet (fresh DB) — nothing to reconcile against
    if (!byNode.has(nodeId)) byNode.set(nodeId, []);
    byNode.get(nodeId)!.push(s);
  }

  const results: NatSyncResult[] = [];
  const errors: string[] = [];

  for (const node of nodes) {
    const nodeServers = byNode.get(node.id) ?? [];
    const intent = planNatRules(nodeServers as unknown as ForwardSource[]);

    // Two data problems that used to be invisible because the old loop just
    // built whatever it was handed. Neither blocks this node's sync — the
    // ruleset installed is still verified end to end — but neither is
    // swallowed either.
    for (const c of intent.conflicts) {
      console.error(
        `[nat] ${node.name}: port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
          `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
      );
    }
    for (const r of intent.rejected) {
      console.error(`[nat] ${node.name}/${r.hostname}: no rule installed — ${r.reason}`);
    }

    try {
      const result = await reconcileNatChain(natHostFor(node, node.natChain), node.natChain, intent);
      if (result.unparsed.length) {
        console.warn(
          `[nat] ${node.name}/${node.natChain} contains ${result.unparsed.length} rule(s) this engine did ` +
            `not write and will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
        );
      }
      console.log(
        `[nat] ${node.name}/${node.natChain} verified: ${result.verified} rule(s) present ` +
          `(+${result.added} / -${result.deleted})`
      );
      results.push(result);
    } catch (e: any) {
      // Collected, not thrown immediately — one node's failure (agent
      // unreachable, no token configured, a genuinely broken ruleset) must
      // never prevent every OTHER node's sync from being attempted.
      const msg = `${node.name}/${node.natChain}: ${String(e?.message ?? e)}`;
      console.error(`[nat] sync FAILED for ${msg}`);
      errors.push(msg);
    }
  }

  if (errors.length) {
    throw new Error(`NAT sync failed for ${errors.length} node(s): ${errors.join(" | ")}`);
  }
  return results;
}

